export const ResizeAdjustmentDirection = {
  /** Move a pane boundary upward; decrease a window's height. */
  Up: "UP",
  /** Move a pane boundary downward; increase a window's height. */
  Down: "DOWN",
  /** Move a pane boundary leftward; decrease a window's width. */
  Left: "LEFT",
  /** Move a pane boundary rightward; increase a window's width. */
  Right: "RIGHT",
} as const;
/**
 * Which edge a resize moves, in tmux's own terms.
 *
 * The direction is where the boundary travels, not which pane grows. For the
 * bottom pane of a vertical split, `Up` takes space from the pane above when
 * the layout permits.
 */
export type ResizeAdjustmentDirection =
  (typeof ResizeAdjustmentDirection)[keyof typeof ResizeAdjustmentDirection];

export const RESIZE_ADJUSTMENT_DIRECTION_FLAG_MAP: Readonly<
  Record<ResizeAdjustmentDirection, string>
> = {
  [ResizeAdjustmentDirection.Up]: "-U",
  [ResizeAdjustmentDirection.Down]: "-D",
  [ResizeAdjustmentDirection.Left]: "-L",
  [ResizeAdjustmentDirection.Right]: "-R",
} as const;

export const WindowDirection = {
  /** Insert before the target window, shifting occupied indices if needed. */
  Before: "BEFORE",
  /** Insert after the target window, shifting occupied indices if needed. */
  After: "AFTER",
} as const;
/**
 * Where a new window lands relative to the one it was created from.
 *
 * tmux inserts at the next index before or after the target and moves the
 * windows above it up to make room, so indices a caller is holding can shift.
 * Without either direction the target index *is* the new window's place.
 */
export type WindowDirection = (typeof WindowDirection)[keyof typeof WindowDirection];

export const WINDOW_DIRECTION_FLAG_MAP: Readonly<Record<WindowDirection, string>> = {
  [WindowDirection.Before]: "-b",
  [WindowDirection.After]: "-a",
} as const;

export const PaneDirection = {
  /** Split top/bottom, placing the new pane above the target. */
  Above: "ABOVE",
  /** Split top/bottom, placing the new pane below the target. */
  Below: "BELOW",
  /** Split left/right, placing the new pane right of the target. */
  Right: "RIGHT",
  /** Split left/right, placing the new pane left of the target. */
  Left: "LEFT",
} as const;
/**
 * Which side of the current pane a split puts the new one on.
 *
 * `Above` and `Left` are the same split as `Below` and `Right` with tmux's
 * `-b` flag, so the geometry is identical and only the occupant differs.
 */
export type PaneDirection = (typeof PaneDirection)[keyof typeof PaneDirection];

export const PANE_DIRECTION_FLAG_MAP: Readonly<Record<PaneDirection, readonly string[]>> = {
  [PaneDirection.Above]: ["-v", "-b"],
  [PaneDirection.Below]: ["-v"],
  [PaneDirection.Right]: ["-h"],
  [PaneDirection.Left]: ["-h", "-b"],
} as const;

declare const defaultOptionScopeBrand: unique symbol;
/**
 * "Whatever scope tmux would use", as a value rather than an absent argument.
 *
 * Branded so it cannot be confused with an {@link OptionScope}: passing this
 * means the call sends no scope flag, which is not the same as sending the
 * session one.
 */
export type DefaultOptionScope = { readonly [defaultOptionScopeBrand]: "default-option-scope" };
export const DEFAULT_OPTION_SCOPE: DefaultOptionScope = {} as DefaultOptionScope;

export const OptionScope = {
  /** Server-wide options, independent of session, window and pane options. */
  Server: "server",
  /** Session options, with inherited global defaults for unset values. */
  Session: "session",
  /** Window options, with inherited global defaults for unset values. */
  Window: "window",
  /** Pane options, inheriting unset values from the window's option table. */
  Pane: "pane",
} as const;
/**
 * Which table an option is read from or written to.
 *
 * The scopes are not one chain. A pane option falls back to the window's, and
 * an unset window or pane option falls back to the global window options; a
 * session option falls back to the global session options, and server options
 * belong to no session, window or pane at all. So setting something at window
 * scope reaches every pane in it that has not set its own, and setting it at
 * session scope does not.
 */
export type OptionScope = (typeof OptionScope)[keyof typeof OptionScope];

export const OPTION_SCOPE_FLAG_MAP: Readonly<Record<OptionScope, string>> = {
  [OptionScope.Server]: "-s",
  [OptionScope.Session]: "",
  [OptionScope.Window]: "-w",
  [OptionScope.Pane]: "-p",
} as const;

export const HOOK_SCOPE_FLAG_MAP: Readonly<Record<OptionScope, string>> = {
  [OptionScope.Server]: "-g",
  [OptionScope.Session]: "",
  [OptionScope.Window]: "-w",
  [OptionScope.Pane]: "-p",
} as const;

packages/libtmux/src/engine.ts.content:
/**
 * Running tmux somewhere other than this machine's `tmux`.
 *
 * Everything above this — capabilities, acquisition, the graph, the handles,
 * the query layer — is built on one operation: execute one structured tmux
 * invocation and return its bytes and status. Replacing that operation moves
 * the whole library to a tmux over SSH, inside a container, or behind a daemon.
 *
 * Deliberately small, and deliberately not the graph. A seam at the graph would
 * make every implementer responsible for framing, capability gating and
 * normalization; a seam here leaves them responsible for execution, which is
 * the part that differs.
 *
 * Global flags and commands stay distinct in the request, so an engine never
 * has to infer their boundary. `guardRequest` keeps an invocation addressed by
 * id from running on a daemon that reissued it. `endpoint` says where the
 * engine reaches, which tells two servers apart when the socket path cannot.
 *
 * `Server.watch` and `Server.connect` are not available through an engine:
 * both hold a local `tmux -C attach` process, and an engine exists because
 * tmux is not somewhere this process can spawn one. They refuse rather than
 * attaching to whichever local daemon answers.
 */

import { guardRequest as guardRequestInternal } from "./_internal/transport/daemon_guard.js";
import {
  flattenInvocation as flattenInvocationInternal,
  MAX_PACKED_ARGV_BYTES as MAX_PACKED_ARGV_BYTES_INTERNAL,
  MAX_PACKED_ARGV_COUNT as MAX_PACKED_ARGV_COUNT_INTERNAL,
} from "./_internal/transport/invocation.js";
import type { AbortLike } from "./types.js";

/**
 * Making a command refuse to run on a daemon that is not the one it was read
 * from.
 *
 * A tmux id is unique within one daemon and reissued by the next: `kill-server`
 * and a restart give a new daemon the same socket, and it numbers its panes from
 * `%0` again. A handle captured before the restart therefore names something
 * that exists, belongs to somebody else, and answers to the same command.
 *
 * Checking first and sending second does not close that: the daemon can change
 * between the two. `if-shell -F` does, because it is not a shell — tmux expands
 * the format inside its command queue and `cmdq_insert_after`s the guarded
 * command into the same queue, so nothing runs in between. The condition is
 * `pid` and `start_time` together, since pids are reused.
 *
 * The refusal has to be visible. tmux answers a false condition with no output
 * and status 0, which is indistinguishable from a command that printed nothing,
 * so the else branch is a freshly named unknown command. A 128-bit suffix makes
 * matching a pre-existing command alias a guess, and the exact diagnostic
 * distinguishes the refusal from the guarded command failing. The guarded
 * command keeps its own stdout and stderr either way.
 */
export type DaemonGuard = {
  readonly pid: string;
  readonly startTime: string;
};

/** One nonempty tmux command, before command-list separators are inserted. */
export type TmuxCommand = readonly [name: string, ...args: string[]];

/**
 * What an engine is asked to run: one ordered command list, and the daemon it
 * must still be talking to.
 *
 * tmux runs a command list until one fails and discards the rest, so the list
 * is the unit of atomicity a caller gets. The daemon guard is what stops a
 * raw tmux id being applied to whatever a restarted server reissued it to.
 */
export type TmuxInvocationRequest = {
  /** Nonempty commands tmux receives as one ordered command list. */
  readonly commands: readonly [TmuxCommand, ...TmuxCommand[]];
  /**
   * Refuse this invocation unless tmux is still the daemon named here.
   *
   * Set when the argv carries a raw tmux id, which a restarted daemon reissues
   * to something else. A spawning transport honours it by wrapping the whole
   * command list in `if-shell -F`.
   */
  readonly daemonGuard?: DaemonGuard;
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly executable: string;
  /** Flags interpreted by the tmux client before the first command. */
  readonly globalArgs: readonly string[];
  /** Require the engine to return stdout without a text protocol changing it. */
  readonly rawOutput?: true;
  /** Cancel the whole invocation, never one command within it. */
  readonly signal?: AbortLike;
  /**
   * Bytes to write to the command's standard input.
   *
   * Caller-facing `CommandOptions` accepts text or bytes. The library
   * encodes text before it reaches the engine seam, so an engine receives only
   * the normalized `Uint8Array` form. Only an unguarded, one-command
   * invocation may carry stdin.
   */
  readonly stdin?: Uint8Array;
  /** A positive timer-safe integer when the request has a deadline. */
  readonly timeoutMs?: number;
};

/** A daemon-guarded request paired with its exact refusal detector. */
export type GuardedTmuxRequest = {
  readonly request: TmuxInvocationRequest;
  readonly refusedBy: (exitCode: number, stderr: Uint8Array) => boolean;
};

/**
 * What an engine reports back: the process's own exit, not tmux's opinion of
 * it.
 *
 * A `returncode` of zero and a `signal` of `null` together mean tmux ran and
 * answered; either one set means it did not finish, and `stderr` says why.
 */
export type TmuxCommandResult = {
  readonly cmd: readonly string[];
  readonly exitCode: number;
  /**
   * The signal that ended the process, as a plain string.
   *
   * Not `NodeJS.Signals`: these declarations are gated to compile with no
   * ambient Node types, and this one is reachable from the package root.
   */
  readonly signal: string | null;
  readonly stderr: Uint8Array;
  readonly stdout: Uint8Array;
};

/**
 * What runs a tmux command for a server.
 *
 * Two obligations beyond returning bytes, and both are what the layers above
 * assume rather than check:
 *
 * Every request is one tmux invocation and carries its ordered command list.
 * Keeping that structure at the seam prevents an engine from splitting a
 * snapshot into several clients or guessing where global flags end.
 * Environment, stdin, signal, and timeout apply once to the whole invocation.
 *
 * The library reads the daemon's version through the engine before the first
 * command, with a `run-shell -C` request whose stderr names the answer, and
 * starts each list with an `if-shell -F` fence that stops the list on a daemon
 * of another release. An engine runs both as it runs any command; a request's
 * stdin belongs to the command after the fence.
 *
 * `daemonGuard`, when a request carries one, must reach tmux — or the engine
 * must be bound to one daemon for its lifetime, the way a control connection
 * is. Ignoring it on a reconnecting engine means a handle read before a restart
 * addressing whatever now holds its id. `guardRequest` is what the built-in
 * engine calls to honour it, published so an implementer does not reproduce
 * the wrapper, its else branch, and the stderr that tells refusal from failure.
 */
export type TmuxEngine = {
  /**
   * Where this engine reaches tmux, as one comparable string.
   *
   * The socket is not the address when an engine is in play: `/tmp/tmux-1000/x`
   * on two machines is two daemons, and comparing servers by socket alone
   * reports them as one. Anything stable and distinct will do — `ssh://host`,
   * a container id, a URL.
   *
   * Optional because only comparison needs it. An engine that leaves it unset
   * is never reported equal to another engine, which is the answer that cannot
   * be wrong when the reach is unknown.
   */
  readonly endpoint?: string;
  execute(request: TmuxInvocationRequest): Promise<TmuxCommandResult>;
};

/**
 * How much of one command a tmux client may hand the server.
 *
 * `client.c` packs the command into a single imsg, and OpenBSD's imsg — and
 * tmux's bundled copy — fix the frame at 16KB. A 16-byte header and the
 * four-byte argument count come out of that, leaving this for the command
 * itself. Global flags and the executable are not packed and do not count.
 *
 * It applies to engines that launch a tmux client with argv; an engine with a
 * different wire protocol must enforce that protocol's own bound.
 */
export const MAX_PACKED_ARGV_BYTES: 16_364 = MAX_PACKED_ARGV_BYTES_INTERNAL;

/**
 * How many arguments of one command a tmux client may hand the server.
 *
 * The other half of the same refusal, and reachable well inside the byte
 * bound: a thousand short arguments are a few kilobytes. tmux 3.7 and later
 * parse 1000 and refuse 1001; older supported releases carry no such check.
 * This package enforces it everywhere, so one invocation means one thing.
 */
export const MAX_PACKED_ARGV_COUNT: 1000 = MAX_PACKED_ARGV_COUNT_INTERNAL;

/** Flatten a validated request into the argv accepted by tmux. */
export const flattenInvocation: (request: TmuxInvocationRequest) => readonly string[] =
  flattenInvocationInternal;

/**
 * Prepare a request so tmux itself refuses it on the wrong daemon.
 *
 * The returned detector is bound to the random command in the transformed
 * request. Keep the pair together until the command completes. A guarded
 * request with stdin is rejected because an `if-shell` branch cannot read the
 * spawning client's stdin.
 */
export const guardRequest: (request: TmuxInvocationRequest) => GuardedTmuxRequest =
  guardRequestInternal;

packages/libtmux/src/errors.ts.content:
import { types as nodeTypes } from "node:util";

import type { DeliveryStatus } from "./common.js";

/**
 * The criteria a lookup was given, carried on the error it raised.
 *
 * Kept as the caller wrote it rather than as a formatted sentence, so a
 * caller that built the criteria from a form or a config file can point at
 * the field that was wrong. The message renders it; this is the source.
 */
export type Query = Readonly<Record<string, unknown>>;

/** What any of these errors accepts: the cause, and the tmux command that ran. */
interface ExceptionOptions {
  readonly cause?: unknown;
  readonly subcommand?: string;
}

/** The criteria that found nothing, and an optional message replacing the built one. */
interface ObjectNotFoundOptions extends ExceptionOptions {
  readonly message?: string;
  readonly query?: Query;
}

/** The criteria that matched too much, with how many it matched when known. */
interface MultipleObjectsErrorOptions extends ObjectNotFoundOptions {
  readonly count?: number;
}

const maximumQueryFormatDepth = 256;
const maximumQueryDepthValue = JSON.stringify("[query value exceeds maximum depth]");

function sortedDataEntries(value: object): readonly (readonly [string, unknown])[] | null {
  try {
    if (nodeTypes.isProxy(value) || Array.isArray(value)) return null;
    const prototype = Object.getPrototypeOf(value) as object | null;
    if (prototype !== Object.prototype && prototype !== null) return null;
    const entries: Array<readonly [string, unknown]> = [];
    for (const key of Reflect.ownKeys(value)) {
      if (typeof key !== "string") return null;
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
        return null;
      }
      entries.push([key, descriptor.value]);
    }
    return entries.sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0));
  } catch {
    return null;
  }
}

function dataArrayValues(value: object): readonly unknown[] | null {
  try {
    if (nodeTypes.isProxy(value) || !Array.isArray(value)) return null;
    const lengthDescriptor = Object.getOwnPropertyDescriptor(value, "length");
    if (
      Object.getPrototypeOf(value) !== Array.prototype ||
      lengthDescriptor === undefined ||
      !("value" in lengthDescriptor) ||
      lengthDescriptor.enumerable ||
      typeof lengthDescriptor.value !== "number" ||
      !Number.isSafeInteger(lengthDescriptor.value) ||
      lengthDescriptor.value < 0 ||
      Reflect.ownKeys(value).length !== lengthDescriptor.value + 1
    ) {
      return null;
    }
    const values: unknown[] = [];
    for (let index = 0; index < lengthDescriptor.value; index += 1) {
      const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
      if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
        return null;
      }
      values.push(descriptor.value);
    }
    return values;
  } catch {
    return null;
  }
}

function formatDataValue(value: unknown, active: Set<object>, depth = 0): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "boolean") return String(value);
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "null";
  if ((typeof value !== "object" && typeof value !== "function") || value === null) {
    return "null";
  }
  if (depth >= maximumQueryFormatDepth) return maximumQueryDepthValue;
  if (active.has(value)) return JSON.stringify("[circular query value]");
  active.add(value);
  try {
    const array = dataArrayValues(value);
    if (array !== null) {
      return `[${array.map((entry) => formatDataValue(entry, active, depth + 1)).join(",")}]`;
    }
    const entries = sortedDataEntries(value);
    if (entries === null) return JSON.stringify("[invalid query value]");
    return `{${entries
      .map(([key, entry]) => `${JSON.stringify(key)}:${formatDataValue(entry, active, depth + 1)}`)
      .join(",")}}`;
  } finally {
    active.delete(value);
  }
}

function formatQuery(query: Query): string {
  const entries = sortedDataEntries(query);
  if (entries === null) return "";
  return entries
    .map(([key, value]) =>
      typeof value === "string"
        ? `${key}='${value}'`
        : `${key}=${formatDataValue(value, new Set())}`,
    )
    .join(", ");
}

/**
 * What a failed `tmux` invocation reported, before it is turned into a message.
 *
 * `args` excludes the connection flags this library adds, so it reads as the
 * command a user would have typed.
 */
export interface TmuxCommandFailureOptions extends ExceptionOptions {
  /** The full argument vector, without the connection flags. */
  readonly args: readonly string[];
  readonly exitCode: number;
  readonly stderr: readonly string[];
  /** Whatever the command printed before it failed. */
  readonly stdout?: readonly string[];
  /** The `-t` target the command addressed, when it had one. */
  readonly target?: string | undefined;
}

/**
 * Every value {@link LibTmuxError.code} can hold.
 *
 * A union rather than `string` so a comparison against a name this package
 * does not have is a type error rather than a branch that never runs.
 *
 * Each class declares this type rather than its own literal because the
 * hierarchy is three deep in places — `NoMatchError` extends
 * `ObjectNotFoundError` — and a literal on the parent makes the child's
 * declaration an illegal override. `instanceof` is the narrowing tool; this
 * is the one that survives a bundler and a serialization round trip.
 */
export type LibTmuxErrorCode =
  | "FormatProtocolError"
  | "LibTmuxError"
  | "MultipleMatchesError"
  | "MultipleObjectsError"
  | "NoMatchError"
  | "ObjectNotFoundError"
  | "QueryValidationError"
  | "OutputLostError"
  | "ProgramStartError"
  | "ServerNotLocalError"
  | "StreamLimitError"
  | "TmuxCommandError"
  | "TmuxObjectNotFoundError"
  | "TmuxServerRestartedError"
  | "TmuxTransportError"
  | "VersionTooLowError"
  | "WaitTimeoutError";

/**
 * The base of every error this library raises.
 *
 * Catching this catches all of them, including the ones a future version
 * adds. `subcommand` names the tmux command that was running, and replaces
 * the class name in `toString()` when it is known — an error reading
 * `list-panes: …` says more than one reading `LibTmuxError: …`.
 */
export class LibTmuxError extends Error {
  /**
   * This class's identifier, declared once per class and written to both
   * {@link code} and `name` on every instance.
   *
   * It is a literal rather than `new.target.name` because a constructor's
   * `name` is its identifier, and a bundler that minifies identifiers renames
   * it: under `--minify`, `new WaitTimeoutError().name` read `"m"`. Anything a
   * consumer branches on has to survive their build, so every subclass
   * declares this and a gate holds each one to its own.
   */
  static readonly code: LibTmuxErrorCode = "LibTmuxError";

  /**
   * Which error this is, as a string that outlives minification, bundling and
   * a serialization round trip — the check to write when `instanceof` cannot
   * reach, across a worker boundary or two copies of the package.
   */
  readonly code: LibTmuxErrorCode;
  readonly subcommand: string | undefined;

  constructor(message = "", options: ExceptionOptions = {}) {
    super(message, options.cause === undefined ? undefined : { cause: options.cause });
    const declared = (new.target as typeof LibTmuxError).code;
    this.name = declared;
    this.code = declared;
    this.subcommand = options.subcommand;
  }

  override toString(): string {
    return this.subcommand === undefined
      ? `${this.name}: ${this.message}`
      : `${this.subcommand}: ${this.message}`;
  }
}

/** What went wrong between this process and tmux, as opposed to inside tmux. */
export type TmuxTransportErrorKind =
  | "cancelled"
  | "contract"
  | "pipe"
  | "protocol"
  | "spawn"
  | "timeout";

/**
 * A command did not complete, and this is how far it got.
 *
 * The reason this is on the error rather than inferred from it: after a
 * timeout, "did tmux run this?" has no default answer, and retrying a mutation
 * that already applied is how one `kill-session` becomes two. `not_started` is
 * the only status a caller may retry blindly.
 */
export class TmuxTransportError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "TmuxTransportError";

  readonly #stderr: Uint8Array;
  readonly #stdout: Uint8Array;
  /** How far the command got before this failure. */
  readonly delivery: DeliveryStatus;
  /** Which part of reaching tmux failed. */
  readonly kind: TmuxTransportErrorKind;
  /**
   * The signal that ended the process, when one did.
   *
   * A plain string rather than Node's `NodeJS.Signals`: these declarations are
   * gated to compile with no ambient Node types, and a consumer compares this
   * against `"SIGKILL"` either way.
   */
  readonly signal: string | null | undefined;

  constructor(message: string, options: TmuxTransportErrorOptions) {
    super(message, {
      ...(options.cause === undefined ? {} : { cause: options.cause }),
      ...(options.subcommand === undefined ? {} : { subcommand: options.subcommand }),
    });
    this.delivery = options.delivery;
    this.kind = options.kind;
    this.signal = options.signal;
    this.#stderr = new Uint8Array(options.stderr ?? []);
    this.#stdout = new Uint8Array(options.stdout ?? []);
  }

  /** Whatever tmux wrote to stderr before the failure, copied. */
  get stderr(): Uint8Array {
    return new Uint8Array(this.#stderr);
  }

  /** Whatever tmux wrote to stdout before the failure, copied. */
  get stdout(): Uint8Array {
    return new Uint8Array(this.#stdout);
  }
}

/**
 * What the transport observed when a command did not come back.
 *
 * `delivery` says how far the command got, which is the part a caller needs
 * to decide whether retrying is safe.
 */
export interface TmuxTransportErrorOptions extends ExceptionOptions {
  readonly delivery: DeliveryStatus;
  readonly kind: TmuxTransportErrorKind;
  readonly signal?: string | null;
  readonly stderr?: Uint8Array;
  readonly stdout?: Uint8Array;
}

/**
 * A lookup that required one object found none.
 *
 * The criteria are on {@link ObjectNotFoundError.query} as they were written,
 * and rendered into the message. Raised by the strict lookups; the lenient
 * ones return `undefined` instead.
 */
export class ObjectNotFoundError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "ObjectNotFoundError";

  readonly query: Query | undefined;

  constructor(options: ObjectNotFoundOptions = {}) {
    const formattedQuery = options.query === undefined ? "" : formatQuery(options.query);
    const message =
      options.message ??
      (formattedQuery === "" ? "No objects found" : `No objects found: ${formattedQuery}`);
    super(message, options);
    this.query = options.query;
  }
}

/**
 * A lookup that required one object found several.
 *
 * `count` is how many, when the lookup counted them. Distinct from
 * {@link ObjectNotFoundError} because the two want opposite fixes: this one
 * needs narrower criteria, that one needs wider.
 */
export class MultipleObjectsError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "MultipleObjectsError";

  readonly count: number | undefined;
  readonly query: Query | undefined;

  constructor(options: MultipleObjectsErrorOptions = {}) {
    const parts = ["Multiple objects returned"];
    if (options.count !== undefined) parts.push(`(${options.count})`);
    const formattedQuery = options.query === undefined ? "" : formatQuery(options.query);
    const message =
      options.message ?? `${parts.join(" ")}${formattedQuery === "" ? "" : `: ${formattedQuery}`}`;
    super(message, options);
    this.count = options.count;
    this.query = options.query;
  }
}

/**
 * A tmux object named by id was not in the list tmux returned.
 *
 * Its message names the listing command that was run, or is the `message`
 * given for an object no listing names.
 */
export class TmuxObjectNotFoundError extends ObjectNotFoundError {
  static override readonly code: LibTmuxErrorCode = "TmuxObjectNotFoundError";

  constructor(
    options: {
      readonly list_cmd?: string;
      readonly list_extra_args?: readonly string[];
      /** Replaces the message built from the listing, for an object no listing names. */
      readonly message?: string;
      readonly obj_id?: string;
      readonly obj_key?: string;
    } = {},
  ) {
    const { list_cmd, list_extra_args, obj_id, obj_key } = options;
    super({
      message:
        options.message ??
        (list_cmd === undefined ||
        list_extra_args === undefined ||
        obj_id === undefined ||
        obj_key === undefined
          ? "Could not find object"
          : `Could not find ${obj_key}=${obj_id} for ${list_cmd} (${list_extra_args.map((value) => `'${value}'`).join(", ")})`),
    });
  }
}

/**
 * A tmux too old for the operation, or a version libtmux does not recognize.
 *
 * Constructed bare for parity with the Python library, which has this name and
 * throws it with no message. Constructed with its parts by this package, so a
 * caller filtering on a field their tmux predates is told which field, which
 * release has it, and which release answered — rather than being handed an
 * empty result that reads as "no object has this".
 *
 * Every command refused for the minimum tmux release carries `delivery` of
 * `not_started` and a `remedy`: upgrade tmux and restart the server, or pin
 * the previous libtmux release.
 */
export class VersionTooLowError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "VersionTooLowError";

  /** The criteria key the caller wrote, when this came from a query. */
  readonly criteriaName?: string;
  /** The tmux that answered, when this came from a query. */
  readonly serverVersion?: string;
  /** The first tmux that has the field, when this came from a query. */
  readonly since?: string;
  /** `not_started` when tmux was refused before the operation could run. */
  readonly delivery?: DeliveryStatus;
  /** What to do about it, when the refusal has a fix the caller controls. */
  readonly remedy?: string;
  /** What was refused, without the remedy: the message up to where `remedy` begins. */
  readonly reason: string;
  /**
   * `false` when the server's report names no release libtmux can place, such
   * as `master`, rather than one below the minimum.
   */
  readonly recognized: boolean;

  constructor(options?: {
    readonly criteriaName: string;
    readonly delivery?: DeliveryStatus;
    /** `false` when `serverVersion` is a report libtmux cannot place, such as `master`. */
    readonly recognized?: boolean;
    readonly remedy?: string;
    readonly serverVersion: string;
    readonly since: string;
  }) {
    const reason =
      options === undefined
        ? ""
        : options.recognized === false
          ? `${options.criteriaName} needs tmux ${options.since} or newer; this server reports "${options.serverVersion}", an unrecognized version, which is refused`
          : `${options.criteriaName} needs tmux ${options.since}; this server is ${options.serverVersion}`;
    super(options?.remedy === undefined ? reason : `${reason}. ${options.remedy}`);
    this.reason = reason;
    this.recognized = options?.recognized !== false;
    if (options === undefined) return;
    this.criteriaName = options.criteriaName;
    this.serverVersion = options.serverVersion;
    this.since = options.since;
    if (options.delivery !== undefined) this.delivery = options.delivery;
    if (options.remedy !== undefined) this.remedy = options.remedy;
  }
}

/**
 * A wait reached its deadline with the condition still unmet.
 *
 * Says nothing about the condition — it may have become true immediately
 * after. A caller that needs to know must read the state again.
 */
export class WaitTimeoutError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "WaitTimeoutError";
}

/**
 * A program's stream copy reached `maxStreamBytes` and stopped. Everything up
 * to the limit was yielded first; the program runs on, uncopied.
 */
export class StreamLimitError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "StreamLimitError";
}

/**
 * A program's output ended without the run's end mark: tmux removed the pane
 * before reading its last output, or something killed its process group.
 * What arrived was yielded first.
 */
export class OutputLostError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "OutputLostError";
}

/** Why a program never ran. */
export type ProgramStartFailure = "not-found" | "not-executable" | "start-directory";

/**
 * A program never ran: `argv[0]` was not found on its `PATH` or is not an
 * executable file, or its `startDirectory` could not be entered. `exitCode`
 * is the status a shell reports for the same failure, 127 or 126.
 */
export class ProgramStartError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "ProgramStartError";
  readonly reason: ProgramStartFailure;
  readonly exitCode: 126 | 127;

  constructor(message: string, reason: ProgramStartFailure) {
    super(message);
    this.reason = reason;
    this.exitCode = reason === "not-found" ? 127 : 126;
  }
}

/**
 * An option needs a tmux server that shares this process's temporary
 * directory, and a file its shell wrote there never arrived: the server is on
 * another machine, in a container, or under another user. The program was not
 * started, and its pane was removed.
 */
export class ServerNotLocalError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "ServerNotLocalError";
}

/** A selection that required exactly one match found none. */
export class NoMatchError extends ObjectNotFoundError {
  static override readonly code: LibTmuxErrorCode = "NoMatchError";
}
/** A selection that required exactly one match found several. */
export class MultipleMatchesError extends MultipleObjectsError {
  static override readonly code: LibTmuxErrorCode = "MultipleMatchesError";
}

/** @deprecated Use {@link QueryValidationReason}. Removed at `0.1.0`. */
export type QueryValidationErrorCode = QueryValidationReason;

/**
 * Which half of a lookup was malformed: the id, or the criteria around it.
 */
export type QueryValidationReason = "invalid-id" | "invalid-query";

/**
 * Criteria that could not be evaluated, rejected before any command ran.
 *
 * This is a caller mistake rather than a tmux one, so nothing was sent and
 * nothing needs undoing. {@link QueryValidationError.reason} separates a bad id
 * from bad criteria, and the path locates the field.
 */
export class QueryValidationError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "QueryValidationError";

  readonly reason: QueryValidationReason;
  /**
   * Where in the criteria the problem is, as keys and array indices.
   *
   * `["windows", "some", "name", "startsWith"]` reads as
   * `windows.some.name.startsWith`, which is what the message renders. Kept
   * apart from the message so a caller that built the criteria from somewhere
   * else — a form, a config file, an MCP client — can point at the right field
   * rather than parse a sentence. Empty when the criteria themselves are not an
   * object at all.
   */
  readonly path: readonly (string | number)[];

  constructor({
    cause,
    reason,
    message,
    path = [],
  }: {
    readonly cause?: unknown;
    readonly reason: QueryValidationReason;
    readonly message: string;
    readonly path?: readonly (string | number)[];
  }) {
    super(message, { cause });
    this.reason = reason;
    this.path = Object.freeze([...path]);
  }
}

/**
 * A handle outlived the daemon that issued its id.
 *
 * tmux numbers a restarted daemon's objects from the start, so `%1` from before
 * the restart names a pane that exists and belongs to somebody else. Raised
 * from two places for one reason: the local check, when an acquisition has
 * already seen the new daemon, and tmux itself, when it has not — the command
 * carries a condition on the daemon's pid and start time and takes a branch
 * that refuses instead of running.
 *
 * `delivery` is always `not_started`: the whole point of the condition is that
 * a refused command never ran, so retrying against a fresh handle is safe.
 *
 * ```ts
 * try {
 *   await pane.kill();
 * } catch (error) {
 *   if (error instanceof TmuxServerRestartedError) {
 *     // Read the server again; this pane's id belongs to another daemon now.
 *   }
 * }
 * ```
 */
export class TmuxServerRestartedError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "TmuxServerRestartedError";

  /** How far the refused command got, which is nowhere. */
  readonly delivery: DeliveryStatus = "not_started";

  constructor(message: string, options: ExceptionOptions = {}) {
    super(message, options);
  }
}

/**
 * A tmux command that exited non-zero.
 *
 * The parts are fields rather than a formatted sentence so callers can branch
 * on them. Matching a message substring is the failure mode this replaces: it
 * breaks silently when tmux rewords, and it cannot distinguish "already in the
 * requested state" from a genuine error.
 */
export class TmuxCommandError extends LibTmuxError {
  static override readonly code: LibTmuxErrorCode = "TmuxCommandError";

  readonly args: readonly string[];
  readonly exitCode: number;
  readonly stderr: readonly string[];
  /**
   * Whatever the command printed before it failed.
   *
   * tmux writes as it goes, so a command that fails part-way has usually said
   * something first. Dropping it loses the only record of how far it got.
   */
  readonly stdout: readonly string[];
  readonly target: string | undefined;

  constructor(options: TmuxCommandFailureOptions) {
    const subcommand = options.args[0] ?? "tmux";
    super(`${subcommand} failed: ${options.stderr.join("; ")}`, {
      ...(options.cause === undefined ? {} : { cause: options.cause }),
      subcommand,
    });
    this.args = Object.freeze([...options.args]);
    this.exitCode = options.exitCode;
    this.stderr = Object.freeze([...options.stderr]);
    this.stdout = Object.freeze([...(options.stdout ?? [])]);
    this.target = options.target;
  }

  /** Whether tmux's own message contains a phrase, without message parsing at call sites. */
  stderrIncludes(phrase: string): boolean {
    return this.stderr.some((line) => line.includes(phrase));
  }
}

/** @deprecated Use {@link LibTmuxError}. Removed at `0.1.0`. */
export { LibTmuxError as LibTmuxException };
/** @deprecated Use {@link ObjectNotFoundError}. Removed at `0.1.0`. */
export { ObjectNotFoundError as ObjectDoesNotExist };
/** @deprecated Use {@link MultipleObjectsError}. Removed at `0.1.0`. */
export { MultipleObjectsError as MultipleObjectsReturned };
/** @deprecated Use {@link TmuxObjectNotFoundError}. Removed at `0.1.0`. */
export { TmuxObjectNotFoundError as TmuxObjectDoesNotExist };
/** @deprecated Use {@link VersionTooLowError}. Removed at `0.1.0`. */
export { VersionTooLowError as VersionTooLow };
/** @deprecated Use {@link WaitTimeoutError}. Removed at `0.1.0`. */
export { WaitTimeoutError as WaitTimeout };
/** @deprecated Use {@link TmuxServerRestartedError}. Removed at `0.1.0`. */
export { TmuxServerRestartedError as TmuxServerRestarted };

