/** The raw text tmux writes, authenticated where it carries an identity. */
export type RawFormatValue<Token extends FormatFieldName> = Token extends keyof FormatValueTypes
  ? FormatValueTypes[Token] extends "pane-id"
    ? PaneId | ""
    : FormatValueTypes[Token] extends "session-id"
      ? SessionId | ""
      : FormatValueTypes[Token] extends "window-id"
        ? WindowId | ""
        : string
  : string;

/** What a caller reads for one field, once the text has been decoded. */
export type DecodedFormatValue<Token extends FormatFieldName> = Token extends keyof FormatValueTypes
  ? FormatValueTypes[Token] extends "pane-id"
    ? PaneId
    : FormatValueTypes[Token] extends "session-id"
      ? SessionId
      : FormatValueTypes[Token] extends "window-id"
        ? WindowId
        : FormatValueTypes[Token] extends "number"
          ? SafeInteger
          : FormatValueTypes[Token] extends "boolean"
            ? boolean
            : Date
  : string;

/** Idiomatic property names layered over a row, carrying decoded values. */
export type AliasedFields<Row, Aliases extends Readonly<Record<string, keyof Row>>> = {
  readonly [Key in keyof Aliases]: Aliases[Key] extends FormatFieldName
    ? null extends Row[Aliases[Key]]
      ? DecodedFormatValue<Aliases[Key]> | null
      : DecodedFormatValue<Aliases[Key]>
    : Row[Aliases[Key]];
};

/** A raw format row whose listed identity fields are present. */
export type RowWithIdentities<Identities extends FormatFieldName> = {
  readonly [Key in FormatFieldName]: Key extends Identities
    ? Exclude<RawFormatValue<Key>, "">
    : RawFormatValue<Key> | null;
};

