/**
 * Which tmux daemon answered, as tmux itself reports it.
 *
 * A socket path names a place, not a process: `kill-server` and a restart give
 * a new daemon the same path, and that daemon numbers its panes from `%0`
 * again. The pid alone is not enough — pids are reused — so the start time goes
 * with it.
 */
export type DaemonIdentity = DaemonGuard;

// The same bound the MCP server and `waitFor` already use, so one number
// answers "how long before this library gives up on tmux".
const DEFAULT_TIMEOUT_MS = 30_000;

/**
 * How to reach a tmux server, and what to assume when it is quiet.
 *
 * Every field is optional and every default is tmux's own, except
 * {@link ServerOptions.environment}, which replaces the process environment
 * rather than extending it, and the socket, which `LIBTMUX_SOCKET_PATH` or
 * `LIBTMUX_SOCKET` choose when neither `socketName` nor `socketPath` is given.
 * Those two name the same thing two ways and are mutually exclusive.
 */
export interface ServerOptions {
  readonly colors?: 256;
  readonly configFile?: string;
  /**
   * The complete environment passed to every spawned `tmux` process.
   *
   * This replaces `process.env`; it is not overlaid on it. Include inherited
   * entries such as `PATH` explicitly when tmux or its shell needs them. Leave
   * this unset to inherit the current process environment unchanged.
   */
  readonly environment?: Readonly<Record<string, string | undefined>>;
  /**
   * How many tmux invocations this server runs at once. Defaults to 16.
   *
   * Every invocation is a tmux client process with its own pipes, so a caller
   * that fans out over a whole server turns its own concurrency into process
   * and descriptor pressure. tmux runs commands on one thread: `bench-modes.ts`
   * measures twelve concurrent creations costing the same twenty-five
   * invocations as twelve sequential ones — twenty-four either way, plus the
   * query that reads the result back — and arriving out of order, so the
   * ceiling bounds the cost without bounding the work. Waiting for a slot spends the request's own deadline,
   * and a request that never gets one fails `not_started`. An invocation that
   * ends in a wait (`wait-for`, a popup or a prompt) takes no slot: it holds a
   * client for as long as the wait, and its release may need one. A program's
   * run is one.
   */
  readonly maxInFlight?: number;
  /**
   * The socket name, passed to tmux as `-L`.
   *
   * With neither `socketName` nor `socketPath` given, the server reads
   * `LIBTMUX_SOCKET_PATH`, else `LIBTMUX_SOCKET`, from
   * {@link ServerOptions.environment}; a variable that is empty or only
   * whitespace counts as unset. With none set it passes tmux no socket, and tmux
   * picks the server: the one `TMUX` names inside tmux, otherwise its default
   * socket. A socket given here is never overridden by either variable.
   */
  readonly socketName?: string;
  /**
   * The socket path, passed to tmux as `-S`.
   *
   * Takes the place of `socketName`; the two are mutually exclusive. See
   * {@link ServerOptions.socketName} for what is used when neither is given.
   */
  readonly socketPath?: string;
  /**
   * Default deadline, in milliseconds, for every command this server runs:
   * 30 seconds unless set. `null` removes it, so commands wait as long as tmux
   * takes.
   *
   * Must be a positive timer-safe integer or `null`. A single call can
   * override it either way. Commands that wait on a person — `display-popup`,
   * `display-menu`, `command-prompt`, `confirm-before`, `display-panes` and
   * `wait-for` — get no default, since bounding them would cut the person off;
   * a deadline passed on the call itself still applies to them.
   */
  readonly timeoutMs?: number | null;
  readonly tmuxBin?: string;
  /**
   * Called once per tmux invocation, after it answers or fails.
   *
   * The seam for logs, traces and metrics. Every command this server runs
   * reports here, a custom engine's included, and an observer cannot change
   * what a command does — see {@link TmuxInvocationObserver}.
   *
   * ```ts
   * const traced = new Server({
   *   onInvocation: (report) => {
   *     console.log(report.commands[0]?.[0], report.durationMs, report.delivery);
   *   },
   * });
   * ```
   */
  readonly onInvocation?: TmuxInvocationObserver;
  /**
   * Run this server's commands somewhere other than a local `tmux`.
   *
   * The built-in engine spawns a process per command; supplying one moves every
   * layer above it — snapshots, queries, handles — to a tmux reached however
   * you reach it. See `libtmux/engine` for what an engine owes its caller.
   *
   * {@link Server.watch} and {@link Server.connect} refuse when an engine is
   * present because their observer is a local tmux process.
   */
  readonly engine?: TmuxEngine;
}

/**
 * How a connection addresses its daemon, as one comparable string.
 *
 * An absolute socket path names the daemon outright. A name does not: it is
 * resolved against `TMUX_TMPDIR` (then the default tmpdir) and a per-user
 * directory, so the tmpdir in force is part of the address. tmux's own default
 * name is `default`, which is why an unnamed connection is not a third case.
 */
function socketAddress(connection: TmuxConnection): string {
  if (connection.socketPath !== undefined) return `path ${connection.socketPath}`;
  const tmpdir = connection.environment.TMUX_TMPDIR ?? "";
  return `name ${tmpdir} ${connection.socketName ?? "default"}`;
}

/**
 * Which tmux this runtime addresses, or `undefined` when that is unknowable.
 *
 * An engine's socket is a path on a machine this process cannot see, so the
 * socket alone does not name the daemon. Unknowable rather than guessed: an
 * engine that declares no endpoint is the one case where answering would mean
 * inventing the fact the comparison turns on.
 */
function serverAddress(runtime: RuntimeContext): string | undefined {
  const socket = socketAddress(runtime.connection);
  if (runtime.engine === undefined) return `local ${socket}`;
  const endpoint = runtime.engine.endpoint;
  if (endpoint === undefined || endpoint === "") return undefined;
  return `engine ${endpoint} ${socket}`;
}

/**
 * Refuse a call that can only reach a tmux this process can spawn.
 *
 * Control mode is a `tmux -C attach` child of this process. An engine exists
 * because tmux is somewhere this process cannot spawn it, so spawning anyway
 * would attach to whatever local tmux happens to be there — and every command
 * afterwards would succeed against the wrong server.
 */
function refuseWithoutLocalTmux(runtime: RuntimeContext, method: string): void {
  if (runtime.engine === undefined) return;
  throw new LibTmuxError(
    `${method}() holds a local tmux control process open, which a server built with an engine has no way to reach. Use snapshot() and the mutating methods, which travel through the engine, or build a Server without one to watch a local daemon.`,
  );
}

/** Judge the daemon a control client is about to join, whatever an earlier answer said. */
async function checkServerVersion(runtime: RuntimeContext): Promise<DaemonGuard> {
  const { daemon, rawVersion } = await checkDaemonVersion(runtime.transport, {
    environment: runtime.connection.environment,
    executable: runtime.connection.executable,
    globalArgs: connectionArguments(runtime.connection),
    ...(runtime.timeoutMs === undefined ? {} : { timeoutMs: runtime.timeoutMs }),
  });
  // Earlier servers can crash or hang while a control client attaches, so the
  // decision is made before any client does.
  if (!releaseAtLeast(rawVersion, capabilitySince("control-mode").raw)) {
    throw new VersionTooLowError({
      criteriaName: "control mode",
      delivery: "not_started",
      serverVersion: rawVersion,
      since: capabilitySince("control-mode").raw,
    });
  }
  return daemon;
}

/**
 * One tmux server, addressed by the socket it listens on.
 *
 * Constructing this starts no process. tmux spawns the daemon on the first
 * command that needs one, and a daemon already listening on that socket is
 * used rather than replaced, so two `Server` values built from the same
 * options address the same tmux.
 *
 * Every command runs only on a daemon of tmux 3.3a or newer, judged by the
 * daemon's own version rather than the client's. A daemon of an earlier
 * release, or an executable that would start one, is refused with
 * {@link VersionTooLowError} before the command has any effect, and a daemon
 * that is replaced after the version check is refused with
 * {@link TmuxServerRestartedError}.
 *
 * Sessions, windows and panes are reached from here and carry the server with
 * them. Handles taken from one daemon do not survive its restart: the
 * replacement numbers panes from `%0` again — see {@link DaemonIdentity}.
 *
 * **What is on here.** A tmux server does a great many things, so this class
 * has a great many members. They fall into a few groups:
 *
 * **Connecting.** `new Server()` passes tmux no socket unless
 * `LIBTMUX_SOCKET_PATH` or `LIBTMUX_SOCKET` is set, and {@link ServerOptions}
 * names another with `socketName` or `socketPath`, which the variables never
 * override. One liveness check answers `false` when nothing is listening, where
 * the other rejects with tmux's reason. A restart on the same socket puts a
 * different daemon there, which the daemon identity tells apart. The
 * control-mode methods need tmux 3.7, each shows up in tmux as an attached
 * client while it is open, and each refuses a server built with an `engine`.
 *
 * - Alive: {@link Server.isAlive}, {@link Server.checkAlive}
 * - Version: {@link Server.version}, {@link Server.versionAtLeast}
 * - Daemon: {@link Server.daemonIdentity}
 * - Built from: {@link Server.socketName}, {@link Server.socketPath},
 *   {@link Server.configFile}, {@link Server.colors}, {@link Server.tmuxBin}
 * - Compare: {@link Server.equals}
 * - Describe: {@link Server.toString}
 * - Control mode: {@link Server.watch}, {@link Server.connect},
 *   {@link Server.withConnection}
 *
 * **Finding one thing.** The existence check takes an exact name and answers
 * `false` when no server is running. To get the object, read a
 * {@link Selection} and ask it for one: `one` throws `NoMatchError` or
 * `MultipleMatchesError` unless exactly one member matches, `oneOrUndefined`
 * answers `undefined` when none does and still throws `MultipleMatchesError`
 * for several, and `first` answers `undefined` for no match and takes the head
 * of several.
 *
 * - Exists: {@link Server.hasSession}
 * - One: {@link Selection.one}, {@link Selection.oneOrUndefined},
 *   {@link Selection.first}
 *
 * **Listing everything.** Each listing resolves to a {@link Selection}, reads
 * tmux afresh, and rejects when the server cannot be reached, so an outage does
 * not read as an empty server. Calling several in a row describes several
 * different instants; a snapshot reads all of them at one instant, which is
 * cheaper and consistent.
 *
 * - Listings: {@link Server.sessions}, {@link Server.windows},
 *   {@link Server.panes}, {@link Server.clients}
 * - At one instant: {@link Server.snapshot}
 *
 * **Querying things and getting around.** A {@link Selection} answers
 * synchronously and issues no tmux command; it describes the instant it was
 * read. Its `where` throws `VersionTooLowError` when a criterion names a field
 * the running tmux lacks. Moving between levels reads nothing either: each step
 * resolves against the snapshot its handle came from, and the way up and across
 * answers `undefined` when nothing is there.
 *
 * - Narrow: {@link Selection.where}, {@link Selection.filter}
 * - Ask: {@link Selection.exists}, {@link Selection.count}
 * - By index: {@link Selection.at}
 * - Leave the selection: {@link Selection.map}, {@link Selection.toArray}
 * - Down: {@link Session.windows}, {@link Session.panes}, {@link Window.panes}
 * - Up: {@link Pane.window}, {@link Pane.session}, {@link Window.session}
 * - Across: {@link Session.activeWindow}, {@link Session.activePane},
 *   {@link Window.activePane}
 *
 * **Changing things.** A new session is detached and resolves to its handle,
 * and a kill terminates the server and every session on it. A batch runs
 * mutations planned through a handle's `plan`, such as {@link Session.plan}, in
 * order and resolves each to what it made, all from one final snapshot. It is
 * not atomic: tmux stops at the first failure and leaves everything before it
 * applied. A command tmux refuses rejects with {@link TmuxCommandError}, which
 * carries tmux's own stderr.
 *
 * {@link Server.newSession}, {@link Server.kill}, and {@link Server.batch}
 *
 * **Running a program.** A program gets a pane of its own with a real
 * terminal, and no shell parses its `argv`. One method resolves with what the
 * program printed once it ends; the other returns the running {@link Program},
 * which owns its pane and ends and removes it on `await using` or
 * {@link Program.kill}. Both need tmux 3.8 and reject with
 * {@link VersionTooLowError} below it.
 *
 * {@link Server.run} and {@link Server.spawn}
 *
 * **Options and hooks.** Reads cover the server's own options, with the values
 * it inherits added on request. The defaults that sessions and windows inherit
 * take a `"session"` or `"window"` scope, and unsetting falls back to tmux's
 * built-in value. Hooks read as a map from name to commands, and setting one
 * replaces its commands unless `append` is set. `getEnvironment` answers
 * `undefined` when tmux carries no entry, and where `unsetEnvironment` drops an
 * entry, `removeEnvironment` keeps it and marks it for removal from the
 * processes tmux starts.
 *
 * - Server options: {@link Server.showOptions},
 *   {@link Server.showResolvedOptions}, {@link Server.setOption},
 *   {@link Server.unsetOption}
 * - Inherited defaults: {@link Server.showGlobalOptions},
 *   {@link Server.setGlobalOption}, {@link Server.unsetGlobalOption}
 * - Hooks: {@link Server.showHooks}, {@link Server.setHook},
 *   {@link Server.unsetHook}
 * - Environment: {@link Server.showEnvironment}, {@link Server.getEnvironment},
 *   {@link Server.setEnvironment}, {@link Server.unsetEnvironment},
 *   {@link Server.removeEnvironment}
 *
 * **Everything else tmux keeps.** A paste buffer reads as lines or as untouched
 * bytes, is stored from a string, is fed through stdin when the data is large
 * or binary, or is written by tmux to a file. A shell command returns the lines
 * it printed, and a condition runs a tmux command when a shell test succeeds.
 * Planned window layouts are checked before anything is created.
 *
 * - Buffers: {@link Server.listBuffers}, {@link Server.showBuffer},
 *   {@link Server.showBufferBytes}, {@link Server.setBuffer},
 *   {@link Server.loadBuffer}, {@link Server.saveBuffer},
 *   {@link Server.deleteBuffer}
 * - Configuration: {@link Server.sourceFile}, {@link Server.listCommands},
 *   {@link Server.validateLayouts}
 * - Shell: {@link Server.runShell}, {@link Server.ifShell}
 *
 * **Things that need a terminal.** Popups, menus, and choosers draw on an
 * attached client, so they live on the pane they open over rather than on the
 * server. With no client attached, the popup and the menu reject because tmux
 * has no current client, while the chooser and search modes do nothing and
 * report success.
 *
 * {@link Pane.displayPopup}, {@link Pane.displayMenu}, {@link Pane.chooseTree},
 * {@link Pane.chooseBuffer}, and {@link Pane.findWindow}
 *
 * Anything tmux can do that is not here is reachable through
 * {@link Server.cmd}, which runs one command and resolves to the lines it
 * printed, or {@link Server.pipeline}, which runs several in order and is not
 * atomic.
 *
 * Save this complete program as `server.ts`. With Bun 1.4.2 or newer,
 * tmux 3.3a or newer, and `libtmux` installed, run `bun run server.ts`.
 * It creates and stops a private tmux server. A failed operation or cleanup
 * exits with an error; a cleanup error names the retained socket directory.
 *
 * ```ts
 * import { strict as assert } from "node:assert";
 * import { mkdtemp, readdir, rm } from "node:fs/promises";
 * import { tmpdir } from "node:os";
 * import { join } from "node:path";
 * import { Server } from "libtmux";
 *
 * const directory = await mkdtemp(join(tmpdir(), "ltx-example-"));
 * const server = new Server({
 *   socketPath: join(directory, "tmux.sock"),
 *   configFile: "/dev/null",
 *   timeoutMs: 5_000,
 * });
 * const failures: unknown[] = [];
 * try {
 *   assert.equal(await server.hasSession("work"), false);
 *   const session = await server.newSession({
 *     name: "work",
 *     windowName: "editor",
 *     shellCommand: "cat",
 *   });
 *   assert.equal(await server.hasSession("work"), true);
 *   const snapshot = await server.snapshot();
 *   assert.equal(snapshot.sessions.one({ name: "work" }).id, session.id);
 *   assert.equal(snapshot.windows.count(), 1);
 *   assert.equal(snapshot.panes.count(), 1);
 *   console.log("work: 1 session, 1 window, 1 pane");
 * } catch (error) {
 *   failures.push(error);
 * } finally {
 *   try {
 *     if ((await readdir(directory)).includes("tmux.sock")) await server.kill();
 *     await rm(directory, { recursive: true });
 *   } catch (error) {
 *     failures.push(new Error(`Cleanup failed; inspect ${directory}`, { cause: error }));
 *   }
 * }
 * if (failures.length > 0) throw new AggregateError(failures, "Example failed");
 * ```
 *
 * @throws TypeError if both `socketName` and `socketPath` are given.
 */
export class Server {
  declare private readonly serverBrand: undefined;

  constructor(...[options]: [options?: ServerOptions]) {
    if (!(this instanceof Server)) {
      throw new TypeError("Server constructor requires a Server instance");
    }
    if (options?.socketName !== undefined && options.socketPath !== undefined) {
      throw new TypeError("socketName and socketPath are mutually exclusive");
    }

    const environment = options?.environment ?? process.env;
    const fromEnvironment: EnvironmentSocket =
      options?.socketName === undefined && options?.socketPath === undefined
        ? socketFromEnvironment(environment)
        : {};
    const socketName = options?.socketName ?? fromEnvironment.socketName;
    const socketPath = options?.socketPath ?? fromEnvironment.socketPath;

    const connection = new TmuxConnection({
      executable: options?.tmuxBin ?? "tmux",
      environment,
      ...(options?.colors === undefined ? {} : { colors: options.colors }),
      ...(options?.configFile === undefined ? {} : { configFile: options.configFile }),
      ...(socketName === undefined ? {} : { socketName }),
      ...(socketPath === undefined ? {} : { socketPath }),
    });
    const runtime = createRuntimeContext({
      connection,
      connectionAlias: randomUUID() as ConnectionAlias,
      daemonEpoch: 0 as DaemonEpoch,
      ...(options?.engine === undefined ? {} : { engine: options.engine }),
      ...(options?.timeoutMs === null
        ? {}
        : { timeoutMs: options?.timeoutMs ?? DEFAULT_TIMEOUT_MS }),
      transport: new BoundedTransport(
        new VersionCheckTransport(options?.engine ?? new NodeSpawnTransport()),
        options?.maxInFlight ?? DEFAULT_MAX_IN_FLIGHT,
        options?.onInvocation,
      ),
    });
    registerServerRuntime(this, runtime, runtimeConstructors);
  }

  /**
   * Run `body` against a connected server, closing it afterwards.
   *
   * The scoped form of {@link connect}, for code that cannot use `await using`
   * — it needs `Symbol.asyncDispose` in the consumer's `lib` — or would rather
   * not manage the lifetime by hand. The connection closes on the way out
   * whether `body` returns or throws.
   *
   * ```ts
   * const opened = await server.withConnection(async (live) => {
   *   await session.newWindow({ name: "build" });
   *   return live.waitFor((current) => current.windows.exists({ name: "build" }));
   * });
   * opened.windows.count({ name: "build" }); // 1
   * ```
   */
  async withConnection<T>(
    body: (live: ConnectedServer) => Promise<T>,
    options?: ConnectOptions,
  ): Promise<T> {
    const live = await this.connect(options);
    try {
      return await body(live);
    } finally {
      await live.close();
    }
  }

  /**
   * The terminal color override; undefined leaves detection to tmux.
   *
   * ```ts
   * new Server({ colors: 256 }).colors; // 256
   * ```
   */
  get colors(): 256 | undefined {
    return runtimeForServerValue(this)?.connection.colors;
  }

  /**
   * The configuration file this server was pointed at, if any.
   *
   * ```ts
   * new Server({ configFile: "~/.tmux.conf" }).configFile;
   * ```
   *
   * ```ts
   * new Server({ configFile: "~/.tmux.conf" }).configFile;
   * ```
   */
  get configFile(): string | undefined {
    return runtimeForServerValue(this)?.connection.configFile;
  }

  /**
   * The socket name this server addresses, if it was named rather than pathed.
   *
   * ```ts
   * new Server({ socketName: "work" }).socketName; // "work"
   * ```
   *
   * ```ts
   * new Server({ socketName: "work" }).socketName; // "work"
   * ```
   */
  get socketName(): string | undefined {
    return runtimeForServerValue(this)?.connection.socketName;
  }

  /**
   * The socket path this server addresses, if it was given one.
   *
   * ```ts
   * new Server({ socketPath: "/tmp/tmux-1000/work" }).socketPath;
   * ```
   *
   * ```ts
   * new Server({ socketPath: "/tmp/tmux-1000/work" }).socketPath;
   * ```
   */
  get socketPath(): string | undefined {
    return runtimeForServerValue(this)?.connection.socketPath;
  }

  /**
   * The tmux executable this server runs.
   *
   * ```ts
   * new Server().tmuxBin; // "tmux"
   * ```
   *
   * ```ts
   * new Server().tmuxBin; // "tmux"
   * ```
   */
  get tmuxBin(): string {
    return runtimeForServerValue(this)?.connection.executable ?? "tmux";
  }

  /**
   * How this server renders in a log line or an error.
   *
   * A server is identified by the socket it talks to, so that is what the
   * description carries; without one the default rendering is `[object Object]`,
   * which says nothing about which of several servers a message is about.
   */
  toString(): string {
    return `Server(${this.socketPath ?? this.socketName ?? "default"})`;
  }

  /**
   * Stream tmux's control-mode notifications until the stream is disposed.
   *
   * A snapshot answers what is true now; this answers what changed. The stream
   * holds one `tmux -C attach-session` process for its lifetime, so it reports
   * events without polling and without a command per read.
   * That process is a tmux-visible attached client until the stream closes; it
   * affects client listings, attachment state, hooks, and related policy.
   *
   * ```ts
   * await using events = server.watch();
   * for await (const event of events) {
   *   if (event.kind === "window-add") console.log(event.windowId);
   * }
   * ```
   *
   * Requires a daemon of tmux 3.7 or newer: earlier servers can crash or hang
   * while a control client attaches. On an earlier daemon iterating the stream
   * raises {@link VersionTooLowError} and no client attaches; poll
   * {@link snapshot} there.
   *
   * The daemon's version is checked just before the client attaches, and an
   * attach cannot carry the version fence, so a daemon replaced in that window
   * is attached to; `-N` keeps the client from starting one.
   *
   * tmux sends a control client no pane output until it attaches, so this
   * attaches to a session; a server with no sessions has nothing to watch.
   *
   * Name that session with `target` when reading pane output. Structural
   * notifications reach the client wherever it attached, but output arrives
   * only for the attached session, and an untargeted watch lands on whichever
   * session tmux considers current. With two sessions on the server that is
   * silence rather than an error.
   */
  watch(options?: WatchOptions): TmuxEventStream {
    const runtime = runtimeForServer(this);
    refuseWithoutLocalTmux(runtime, "watch");
    return watchServer(runtime.connection, options, runtime.transport, () =>
      checkServerVersion(runtime),
    );
  }

  /**
   * Bind this server to one control-mode connection and return it.
   *
   * The returned server has the same API and shares one control connection for
   * events and daemon-lifetime tracking. Commands use ordinary tmux processes:
   * control mode cannot frame arbitrary command output truthfully when aliases
   * and waiting commands are allowed.
   * The connection has the attached-client lifecycle described by
   * {@link watch} until it closes.
   *
   * ```ts
   * await using live = await server.connect();
   * for await (const event of live.subscribe()) {
   *   if (event.kind === "window-add") console.log((await live.snapshot()).windows.count());
   * }
   * ```
   *
   * Requires a daemon of tmux 3.7 or newer, and rejects with
   * {@link VersionTooLowError} on an earlier one before any client attaches.
   *
   * The version check and the attach are two steps, as for {@link watch}.
   *
   * Each snapshot acquisition remains one atomic tmux invocation containing
   * its daemon identity read and all four listings. The first connected
   * snapshot also follows the observer authentication and version probes.
   */
  async connect(options?: ConnectOptions): Promise<ConnectedServer> {
    if (options !== undefined && "pauseAfterSeconds" in options) {
      throw new TypeError("pauseAfterSeconds belongs to Server.watch(), not Server.connect()");
    }
    for (const removed of ["maxCommandBytes", "maxPendingCommands"] as const) {
      if (options !== undefined && removed in options) {
        throw new TypeError(
          `${removed} was removed; Server.connect() observes events and commands use the server engine`,
        );
      }
    }
    const runtime = runtimeForServer(this);
    refuseWithoutLocalTmux(runtime, "connect");
    const commands = runtime.transport;
    const connection = new ControlConnection(
      runtime.connection,
      options,
      false,
      commands,
      undefined,
      () => checkServerVersion(runtime),
    );
    try {
      await connection.ready();
    } catch (error) {
      await connection.close();
      if (error instanceof VersionTooLowError) throw error;
      throw new LibTmuxError(
        error instanceof Error ? error.message : "tmux control mode could not attach",
        { cause: error },
      );
    }
    const connectedCommands: CommandTransport = observerBoundTransport({
      commands,
      connection: runtime.connection,
      observer: connection,
    });
    const boundRuntime = createRuntimeContext({
      connection: runtime.connection,
      connectionAlias: randomUUID() as ConnectionAlias,
      daemonEpoch: 0 as DaemonEpoch,
      ...(runtime.timeoutMs === undefined ? {} : { timeoutMs: runtime.timeoutMs }),
      transport: connectedCommands,
    });
    return createConnectedServer(boundRuntime, runtimeConstructors, connection);
  }

  /**
   * Acquire an immutable view of the server at this instant.
   *
   * Acquisition is the only step that talks to tmux. Everything reachable from
   * the returned value resolves locally, so traversal and filtering issue no
   * commands and an earlier snapshot keeps reporting its own instant.
   * `daemonIdentity` identifies the daemon captured with these collections.
   *
   * ```ts
   * const now = await server.snapshot();
   * now.daemonIdentity.pid;
   * now.windows.count();
   * ```
   */
  snapshot(options: SnapshotOptions = {}): Promise<ServerSnapshot> {
    return buildServerSnapshot(this, runtimeForServer(this), options.signal);
  }

  /**
   * Every session on the server, read now.
   *
   * This and its three siblings each take a snapshot of their own — one daemon
   * identity read and four listings per call — so calling several in a row
   * describes several different instants and pays for each. Inside a loop that
   * is an N+1: prefer one
   * {@link snapshot} and read `sessions`, `windows`, `panes`, and `clients`
   * off it, which is both cheaper and consistent.
   *
   * Save this complete program as `sessions.ts`. With Bun 1.4.2 or newer,
   * tmux 3.3a or newer, and `libtmux` installed, run `bun run sessions.ts`.
   * It creates and stops a private tmux server. A failed operation or cleanup
   * exits with an error; a cleanup error names the retained socket directory.
   *
   * ```ts
   * import { strict as assert } from "node:assert";
   * import { mkdtemp, readdir, rm } from "node:fs/promises";
   * import { tmpdir } from "node:os";
   * import { join } from "node:path";
   * import { Server, NoMatchError } from "libtmux";
   *
   * const directory = await mkdtemp(join(tmpdir(), "ltx-example-"));
   * const server = new Server({
   *   socketPath: join(directory, "tmux.sock"),
   *   configFile: "/dev/null",
   *   timeoutMs: 5_000,
   * });
   * const failures: unknown[] = [];
   * try {
   *   await server.newSession({ name: "prod-api", shellCommand: "cat" });
   *   await server.newSession({ name: "dev-api", shellCommand: "cat" });
   *   const sessions = await server.sessions();
   *   assert.equal(sessions.count(), 2);
   *   console.log(
   *     "sessions:",
   *     sessions
   *       .map((item) => item.name)
   *       .sort()
   *       .join(", "),
   *   );
   *   const production = sessions.where({ name: { startsWith: "prod-" } }).one();
   *   assert.equal(production.name, "prod-api");
   *   console.log("production:", production.name);
   *   assert.equal(sessions.oneOrUndefined({ name: "missing" }), undefined);
   *   try {
   *     sessions.one({ name: "missing" });
   *     throw new Error("Expected the missing session to fail lookup");
   *   } catch (error) {
   *     if (!(error instanceof NoMatchError)) throw error;
   *     console.log("missing:", error.code);
   *   }
   * } catch (error) {
   *   failures.push(error);
   * } finally {
   *   try {
   *     if ((await readdir(directory)).includes("tmux.sock")) await server.kill();
   *     await rm(directory, { recursive: true });
   *   } catch (error) {
   *     failures.push(new Error(`Cleanup failed; inspect ${directory}`, { cause: error }));
   *   }
   * }
   * if (failures.length > 0) throw new AggregateError(failures, "Example failed");
   * ```
   */
  async sessions(): Promise<Selection<Session>> {
    return (await this.snapshot()).sessions;
  }

  /**
   * Every window on the server, including each placement of a linked window.
   *
   * Save this complete program as `windows.ts`. With Bun 1.4.2 or newer,
   * tmux 3.3a or newer, and `libtmux` installed, run `bun run windows.ts`.
   * It creates and stops a private tmux server. A failed operation or cleanup
   * exits with an error; a cleanup error names the retained socket directory.
   *
   * ```ts
   * import { strict as assert } from "node:assert";
   * import { mkdtemp, readdir, rm } from "node:fs/promises";
   * import { tmpdir } from "node:os";
   * import { join } from "node:path";
   * import { Server, MultipleMatchesError } from "libtmux";
   *
   * const directory = await mkdtemp(join(tmpdir(), "ltx-example-"));
   * const server = new Server({
   *   socketPath: join(directory, "tmux.sock"),
   *   configFile: "/dev/null",
   *   timeoutMs: 5_000,
   * });
   * const failures: unknown[] = [];
   * try {
   *   const session = await server.newSession({
   *     name: "home",
   *     windowName: "editor",
   *     shellCommand: "cat",
   *   });
   *   const guest = await server.newSession({
   *     name: "guest",
   *     windowName: "shell",
   *     shellCommand: "cat",
   *   });
   *   const window = await session.newWindow({ name: "logs", shellCommand: "cat" });
   *   await window.link({ session: guest });
   *   const windows = await server.windows();
   *   const logs = windows.where({ name: "logs" });
   *   assert.equal(logs.count(), 2);
   *   console.log("logs placements:", logs.count());
   *   try {
   *     logs.one();
   *     throw new Error("Expected a linked window lookup to be ambiguous");
   *   } catch (error) {
   *     if (!(error instanceof MultipleMatchesError)) throw error;
   *     console.log("ambiguous:", error.code);
   *   }
   *   const placed = logs.one({ session: { is: { name: "home" } } });
   *   assert.equal(placed.id, window.id);
   *   console.log("selected placement:", placed.session?.name);
   *   console.log(
   *     "linked sessions:",
   *     placed.linkedSessions
   *       .map((item) => item.name)
   *       .sort()
   *       .join(", "),
   *   );
   * } catch (error) {
   *   failures.push(error);
   * } finally {
   *   try {
   *     if ((await readdir(directory)).includes("tmux.sock")) await server.kill();
   *     await rm(directory, { recursive: true });
   *   } catch (error) {
   *     failures.push(new Error(`Cleanup failed; inspect ${directory}`, { cause: error }));
   *   }
   * }
   * if (failures.length > 0) throw new AggregateError(failures, "Example failed");
   * ```
   */
  async windows(): Promise<Selection<Window>> {
    return (await this.snapshot()).windows;
  }

  /**
   * Every pane on the server.
   *
   * Save this complete program as `panes.ts`. With Bun 1.4.2 or newer,
   * tmux 3.3a or newer, and `libtmux` installed, run `bun run panes.ts`.
   * It creates and stops a private tmux server. A failed operation or cleanup
   * exits with an error; a cleanup error names the retained socket directory.
   *
   * ```ts
   * import { strict as assert } from "node:assert";
   * import { mkdtemp, readdir, rm } from "node:fs/promises";
   * import { tmpdir } from "node:os";
   * import { join } from "node:path";
   * import { Server, PaneDirection } from "libtmux";
   *
   * const directory = await mkdtemp(join(tmpdir(), "ltx-example-"));
   * const server = new Server({
   *   socketPath: join(directory, "tmux.sock"),
   *   configFile: "/dev/null",
   *   timeoutMs: 5_000,
   * });
   * const failures: unknown[] = [];
   * try {
   *   const session = await server.newSession({
   *     name: "work",
   *     windowName: "editor",
   *     shellCommand: "cat",
   *   });
   *   const pane = session.panes.one();
   *   await pane.split({ direction: PaneDirection.Below, shellCommand: "cat" });
   *   const panes = await server.panes();
   *   assert.equal(panes.count(), 2);
   *   const active = panes.where({ active: true });
   *   assert.equal(active.count(), 1);
   *   console.log("panes:", panes.count(), "active:", active.count());
   *   for (const item of panes) {
   *     assert.equal(item.session?.name, "work");
   *     assert.equal(item.window?.name, "editor");
   *     console.log("location:", item.session?.name, item.window?.name);
   *   }
   * } catch (error) {
   *   failures.push(error);
   * } finally {
   *   try {
   *     if ((await readdir(directory)).includes("tmux.sock")) await server.kill();
   *     await rm(directory, { recursive: true });
   *   } catch (error) {
   *     failures.push(new Error(`Cleanup failed; inspect ${directory}`, { cause: error }));
   *   }
   * }
   * if (failures.length > 0) throw new AggregateError(failures, "Example failed");
   * ```
   */
  async panes(): Promise<Selection<Pane>> {
    return (await this.snapshot()).panes;
  }

  /**
   * Which daemon is answering on this socket right now.
   *
   * A socket path names a place, not a process. `kill-server` followed by a
   * restart puts a different daemon at the same path, and that daemon numbers
   * its panes from `%0` again — so a handle held across the restart names an
   * object that no longer exists, at an id something else now has. Comparing
   * this before and after is how a long-running caller can tell.
   *
   * A reachable daemon reports its identity even when it has no sessions. An
   * unreachable server rejects instead of returning an absent identity.
   *
   * ```ts
   * const before = await server.daemonIdentity();
   * const after = await server.daemonIdentity();
   * before.pid === after.pid;
   * ```
   */
  async daemonIdentity(options: SnapshotOptions = {}): Promise<DaemonIdentity> {
    const graph = await acquireServerGraph(runtimeForServer(this), options.signal);
    const identity = graph.capture.daemon;
    if (identity === undefined) {
      throw new LibTmuxError("live acquisition omitted the daemon identity");
    }
    return identity;
  }

  /**
   * Every client attached to the server.
   *
   * ```ts
   * const clients = await server.clients();
   * clients.map((entry) => entry.tty);
   * ```
   */
  async clients(): Promise<Selection<Client>> {
    return (await this.snapshot()).clients;
  }

  /**
   * Every server-scope option tmux currently reports.
   *
   * ```ts
   * const options = await server.showOptions();
   * options.get("escape-time");
   * ```
   */
  showOptions(options?: CommandOptions): Promise<ReadonlyMap<string, string>> {
    return showOptions(runtimeForServer(this), "server", null, options);
  }

  /**
   * The option values that govern this server, own and inherited together.
   *
   * `showOptions` reports only what was set here, which for a fresh server is
   * often nothing. This resolves what it inherits as well, so an option has an
   * answer wherever it was actually set.
   *
   * ```ts
   * (await server.showResolvedOptions()).get("message-limit");
   * ```
   */
  showResolvedOptions(options?: CommandOptions): Promise<ReadonlyMap<string, string>> {
    return showResolvedOptions(runtimeForServer(this), "server", null, options);
  }

  /**
   * Set a server-scope option.
   *
   * ```ts
   * await server.setOption("escape-time", "0");
   * ```
   */
  setOption(name: string, value: string, options?: SetOptionOptions): Promise<void> {
    return setOption(runtimeForServer(this), "server", null, name, value, options);
  }

  /**
   * Remove a server-scope option.
   *
   * ```ts
   * await server.unsetOption("escape-time");
   * ```
   */
  unsetOption(name: string): Promise<void> {
    return unsetOption(runtimeForServer(this), "server", null, name);
  }

  /**
   * Write a paste buffer to a file instead of reading it back.
   *
   * `showBuffer` returns the contents through this process; for a large buffer
   * that means holding it in memory to put it somewhere else. tmux writes the
   * file itself, on the machine tmux is running on.
   *
   * ```ts
   * await server.saveBuffer("captured", "/tmp/build.log");
   * ```
   */
  saveBuffer(name: string, path: string, options?: SaveBufferOptions): Promise<void> {
    return saveBuffer(runtimeForServer(this), name, path, options);
  }

  /**
   * Read the defaults every session or window inherits.
   *
   * Most of tmux's options live here rather than on an object: a session that
   * has set nothing reports nothing, while the values actually governing it
   * are these. `history-limit` and `default-shell` are both global session
   * options and `remain-on-exit` a global window one; none of the three is
   * readable any other way.
   *
   * ```ts
   * const defaults = await server.showGlobalOptions("session");
   * defaults.get("default-shell");
   * ```
   */
  showGlobalOptions(
    scope: "session" | "window",
    options?: CommandOptions,
  ): Promise<ReadonlyMap<string, string>> {
    return showOptions(runtimeForServer(this), scope, null, { ...options, global: true });
  }

  /**
   * Set a default every session or window inherits.
   *
   * ```ts
   * await server.setGlobalOption("session", "history-limit", "50000");
   * ```
   */
  setGlobalOption(
    scope: "session" | "window",
    name: string,
    value: string,
    options?: SetOptionOptions,
  ): Promise<void> {
    return setOption(runtimeForServer(this), scope, null, name, value, {
      ...options,
      global: true,
    });
  }

  /**
   * Remove a default, so tmux falls back to its own built-in value.
   *
   * ```ts
   * await server.unsetGlobalOption("session", "history-limit");
   * ```
   */
  unsetGlobalOption(scope: "session" | "window", name: string): Promise<void> {
    return unsetOption(runtimeForServer(this), scope, null, name, { global: true });
  }

  /**
   * Every global hook tmux currently reports.
   *
   * A hook is an array of commands, keyed by the name `setHook` takes, so
   * what was set reads back under the name it was set with. tmux prints each
   * element as `name[0]`, which composes with neither of the writers.
   *
   * ```ts
   * const hooks = await server.showHooks();
   * hooks.get("session-created")?.[0];
   * ```
   */
  showHooks(): Promise<ReadonlyMap<string, readonly string[]>> {
    return showHooks(runtimeForServer(this), "server");
  }

  /**
   * Bind a tmux command to a global hook.
   *
   * A hook holds a list of commands. Without `append` this writes the whole
   * list, so it replaces whatever the hook already ran.
   *
   * ```ts
   * await server.setHook("session-created", "display-message 'hello'");
   * await server.setHook("session-created", "display-message 'and this'", { append: true });
   * ```
   */
  setHook(name: string, command: string, options?: SetHookOptions): Promise<void> {
    return setHook(runtimeForServer(this), "server", null, name, command, options);
  }

  /**
   * Remove a global hook.
   *
   * ```ts
   * await server.unsetHook("session-created");
   * ```
   */
  unsetHook(name: string): Promise<void> {
    return unsetHook(runtimeForServer(this), "server", null, name);
  }

  /**
   * Check every planned window layout before setup scripts or mutations.
   *
   * Names accept unique abbreviations. Only version-sensitive layouts query the
   * daemon; a cold endpoint uses the selected client. Checksums, bounded tree
   * structure and pane counts are checked locally; tmux owns geometry and pruning.
   * Custom layouts are limited to 8192 characters and 256 classic groups.
   * JSON layouts require tmux 3.8 and permit at most 200 nested objects.
   *
   * @throws TypeError when a layout, pane count or version reply is invalid.
   * @throws TmuxCommandError when the daemon or client version cannot be read.
   * @throws TmuxTransportError when validation is cancelled or a version probe fails.
   *
   * ```ts
   * await server.validateLayouts([
   *   { layout: "even-h", panes: 2 },
   *   { layout: "tiled", panes: 1 },
   * ]);
   * ```
   */
  validateLayouts(
    layouts: readonly { readonly layout: string; readonly panes: number }[],
    options?: CommandOptions,
  ): Promise<void> {
    return validateLayouts(runtimeForServer(this), layouts, options);
  }

  /**
   * The tmux version this server is running.
   *
   * The version is probed once per connection and cached with the rest of the
   * server's capabilities, so asking repeatedly costs nothing after the first.
   *
   * ```ts
   * const version = await server.version();
   * version.major; // 3
   * ```
   */
  async version(): Promise<TmuxVersion> {
    return (await runtimeForServer(this).capabilities.bind()).tmuxVersion;
  }

  /**
   * Whether this server is at least `minimum`, written the way tmux writes it.
   *
   * This is how a caller gates on a feature that arrived in a known release
   * without parsing `#{version}` themselves. A named development build such
   * as `next-3.9` has not shipped the release it names: it is at least
   * `3.8`, but not at least `3.9`. A candidate such as `X.Y-rcN` ranks the
   * same way, below `X.Y` and above the release before it. `minimum` must be a
   * form tmux prints, such as `3.7a`, or the call throws a `TypeError`.
   *
   * ```ts
   * if (await server.versionAtLeast("3.5")) {
   *   await server.setHook("command-error", "display-message 'a command failed'");
   * }
   * ```
   */
  async versionAtLeast(minimum: string): Promise<boolean> {
    return tmuxVersionAtLeast(await this.version(), parseTmuxVersion(minimum));
  }

  /**
   * Every variable in the server's global environment.
   *
   * A `null` value is tmux's `-NAME`: present, and marked for removal from any
   * process tmux starts.
