   * } finally {
   *   try {
   *     if ((await readdir(directory)).includes("tmux.sock")) await server.kill();
   *     await rm(directory, { recursive: true });
   *   } catch (error) {
   *     failures.push(new Error(`Cleanup failed; inspect ${directory}`, { cause: error }));
   *   }
   * }
   * if (failures.length > 0) throw new AggregateError(failures, "Example failed");
   * ```
   */
  newSession(options?: NewSessionOptions): Promise<Session> {
    return newSession(this, runtimeForServer(this), options);
  }

  /**
   * Terminate the tmux server and every session on it.
   *
   * ```ts
   * await server.kill();
   * ```
   */
  kill(): Promise<void> {
    return killServer(runtimeForServer(this));
  }

  /**
   * Whether a session with this name exists.
   *
   * The name is matched exactly, including one holding "." or ":". tmux
   * normally accepts a unique prefix as a session target, which would make
   * checking `work` answer yes for `workspace`; this method does not, and it
   * lists every session and compares in JavaScript rather than asking tmux
   * to resolve a target, since no target spelling is both exact and correct
   * for a name holding a target separator. No server running on the socket
   * answers `false`; any other failure to list sessions raises rather than
   * being read as "no such session".
   *
   * ```ts
   * if (!(await server.hasSession("work"))) {
   *   await server.newSession({ name: "work" });
   * }
   * ```
   */
  hasSession(name: string): Promise<boolean> {
    return hasSession(runtimeForServer(this), name);
  }

  /**
   * Run a tmux config file against this server.
   *
   * tmux does not expand `~` here. `source-file` joins a path that is not
   * absolute to the client's working directory and globs the result, so
   * `"~/.tmux.conf"` looks for a directory literally named `~`. Typing it at a
   * shell works because the shell expands it first; passing it as a string
   * never does.
   *
   * ```ts
   * await server.sourceFile(`${process.env["HOME"] ?? "."}/.tmux.conf`);
   * ```
   */
  sourceFile(path: string): Promise<void> {
    return sourceFile(runtimeForServer(this), path);
  }

  /**
   * Every command name the running tmux understands.
   *
   * ```ts
   * const commands = await server.listCommands();
   * commands.includes("new-window"); // true
   * ```
   */
  listCommands(): Promise<readonly string[]> {
    return listCommands(runtimeForServer(this));
  }

  /**
   * Fill a paste buffer from data fed through tmux's stdin.
   *
   * Use this over {@link Server.setBuffer} for anything large or binary: that
   * one passes its data as a command-line argument, and this one does not.
   *
   * ```ts
   * await server.loadBuffer("payload", new Uint8Array([0x68, 0x69]));
   * ```
   */
  loadBuffer(name: string, data: string | Uint8Array): Promise<void> {
    return loadBuffer(runtimeForServer(this), name, data);
  }

  /**
   * Put a string into a named paste buffer.
   *
   * Empty data stores nothing. tmux exits zero for `set-buffer -b name ""` and
   * creates no buffer at all, so the name a caller thinks they just wrote is
   * absent — and they learn that from whatever reads it next, which points at
   * the wrong call. Check before storing content that may be empty.
   *
   * ```ts
   * await server.setBuffer("greeting", "hello");
   * ```
   */
  setBuffer(name: string, data: string): Promise<void> {
    return setBuffer(runtimeForServer(this), name, data);
  }

  /**
   * Read a named paste buffer's contents.
   *
   * ```ts
   * const lines = await server.showBuffer("greeting");
   * lines[0]; // "hello"
   * ```
   */
  showBuffer(name: string): Promise<readonly string[]> {
    return showBuffer(runtimeForServer(this), name);
  }

  /**
   * Read a named paste buffer without decoding or splitting its bytes.
   *
   * Unlike {@link Server.showBuffer}, this preserves NUL, invalid UTF-8, line
   * endings, and trailing newlines.
   *
   * ```ts
   * const bytes = await server.showBufferBytes("payload");
   * bytes[0]; // 104
   * ```
   */
  showBufferBytes(name: string): Promise<Uint8Array> {
    return showBufferBytes(runtimeForServer(this), name);
  }

  /**
   * Every buffer name this server holds.
   *
   * ```ts
   * const names = await server.listBuffers();
   * names.length;
   * ```
   */
  listBuffers(): Promise<readonly string[]> {
    return listBuffers(runtimeForServer(this));
  }

  /**
   * Discard a named paste buffer.
   *
   * Requires tmux 3.4 or newer. Earlier releases can discard an unrelated
   * buffer when the named one is missing, so they raise
   * {@link VersionTooLowError} and discard nothing.
   *
   * ```ts
   * await server.deleteBuffer("greeting");
   * ```
   */
  deleteBuffer(name: string): Promise<void> {
    return deleteBuffer(runtimeForServer(this), name);
  }

  /**
   * Run a shell command through tmux and return whatever it printed.
   *
   * `signal` and `timeoutMs` bound this call's own wait; the tmux server owns
   * and runs `run-shell` itself, decoupled from this client, so neither one
   * stops the command - only this call's own promise settling early.
   *
   * Requires tmux 3.5 or newer. tmux 3.3a and 3.4 print a clientless
   * `run-shell`'s output to a view-mode pane, so they raise
   * {@link VersionTooLowError}; `cmd("run-shell", …)` runs the command there
   * without its output.
   *
   * ```ts
   * const lines = await server.runShell("echo hello");
   * lines[0]; // "hello"
   * ```
   */
  runShell(command: string, options?: RunShellOptions): Promise<readonly string[]> {
    return runShell(runtimeForServer(this), command, options);
  }

  /**
   * Start a program in a pane of its own and return it running.
   *
   * No shell parses `argv`: `["echo", "$HOME"]` prints `$HOME`, and `cd` or
   * a pipe needs `["sh", "-c", …]`. The program gets a real terminal, so a
   * full-screen program can be driven by keys; {@link SpawnOptions} says what
   * that means for pagers and prompts.
   *
   * The {@link Program} owns its pane, in a detached session of its own
   * unless `from` places it beside another pane: `await using` or
   * {@link Program.kill} ends the program and removes it, and tmux does once
   * this process stops renewing its lease, unless `orphanAfterMs` is `null`.
   * Like a child process, a running program keeps this process alive until it
   * ends.
   *
   * Keys go to the terminal at once. A program that reads lines, like `cat`,
   * reads them when it gets there; a full-screen one, like vim, can drop keys
   * that arrive before it has set up its terminal, so wait for its first
   * screen with {@link Pane.waitForText} before typing.
   *
   * Requires tmux 3.8 or newer, and raises {@link VersionTooLowError}
   * below it. Earlier releases have no exit event to wait on, and through
   * 3.7c a dead pane never closes the pipe `stream` reads.
   *
   * @throws TypeError, before tmux sees anything, for an `argv` that is not a
   * non-empty array of strings, a `startDirectory` that is not a string, or a
   * count out of its range or options that do not go together.
   *
   * ```ts
   * await using cat = await server.spawn(["cat"]);
   * await cat.pane.sendKeys("hello");
   * await cat.pane.sendKeys("C-d", { enter: false });
   * const { exitCode } = await cat.wait(); // 0
   * ```
   */
  async spawn(argv: readonly string[], options?: SpawnOptions): Promise<Program> {
    // Typed for run alone: nothing would read a spawn's stderr file.
    if (
      options !== undefined &&
      "separateStderr" in options &&
      options.separateStderr !== undefined
    ) {
      throw new TypeError("separateStderr is a run option; a spawn's stderr stays on its terminal");
    }
    return spawnProgram(this, runtimeForServer(this), argv, options, options?.signal);
  }

  /**
   * Run a program to completion in a pane of its own and return what it printed.
   *
   * The output is the terminal's, scrollback included, with nothing typed
   * before it. The pane is removed before this returns, whatever happened,
   * unless `keep` leaves it for a person to read. Without `from` its session
   * goes too, and a server with no other session then exits, unless its
   * `exit-empty` option is off; the next run starts it again.
   * `input` gives the program a stdin; otherwise it has only the terminal.
   * A program that never ran, because `argv[0]` was not found or is not
   * executable, or `startDirectory` could not be entered, rejects with
   * {@link ProgramStartError}, whose `exitCode` is a shell's 127 or 126.
   * A program still running at `timeoutMs` is ended, SIGTERM and then
   * SIGKILL, and the result has `timedOut` set, since the run owns the
   * program; one aborted through `signal` is ended and the call rejects.
   * Should this process die first, tmux itself ends the program and removes
   * its pane within `orphanAfterMs`, a minute by default.
   *
   * Requires tmux 3.8 or newer, like {@link Server.spawn}.
   *
   * @throws TypeError, before tmux sees anything, for an `argv` that is not a
   * non-empty array of strings, a `startDirectory` that is not a string, or a
   * count out of its range or options that do not go together.
   *
   * ```ts
   * const result = await server.run(["git", "--version"]);
   * result.success; // true
   * result.output.startsWith("git version"); // true
   * ```
   */
  run(argv: readonly string[], options?: RunOptions): Promise<ProgramResult> {
    return runProgram(this, runtimeForServer(this), argv, options);
  }

  /**
   * Run one command or another depending on a condition.
   *
   * ```ts
   * await server.ifShell("test -d /tmp", "display-message 'present'");
   * ```
   */
  ifShell(condition: string, command: string, options?: IfShellOptions): Promise<void> {
    return ifShell(runtimeForServer(this), condition, command, options);
  }

  /**
   * Whether the tmux server is reachable.
   *
   * A missing daemon, socket, or tmux executable answers false. Cancellation,
   * a command deadline, or an engine programming error still raises: none says
   * whether the server is alive.
   *
   * ```ts
   * if (await server.isAlive()) {
   *   await server.snapshot();
   * }
   * ```
   */
  isAlive(): Promise<boolean> {
    return isAlive(runtimeForServer(this));
  }

  /**
   * Assert the server is reachable, raising with tmux's reason if not.
   *
   * Every read already raises on an unreachable server, so this is not what
   * tells an empty result from a missing one — it is the assertion form of
   * {@link isAlive}, for a caller that wants the check and the reason without a
   * read to hang it on.
   *
   * ```ts
   * await server.checkAlive(); // throws when no tmux server is listening
   * ```
   */
  checkAlive(): Promise<void> {
    return checkAlive(runtimeForServer(this));
  }

  /**
   * Assert the server is reachable, raising with tmux's reason if not.
   *
   * @deprecated Use {@link checkAlive}. Removed at `0.1.0`.
   *
   * ```ts
   * await server.raiseIfDead(); // throws when no tmux server is listening
   * ```
   */
  raiseIfDead(): Promise<void> {
    return this.checkAlive();
  }

  /**
   * Run a tmux command this package does not model.
   *
   * tmux has many more commands than any wrapper types. Rather than leaving a
   * caller to build their own subprocess — and reproduce the socket, the
   * environment, the deadline, and the error handling — this runs one through
   * the same path every other operation uses.
   *
   * ```ts
   * await server.cmd("list-keys", ["-T", "copy-mode"]);
   * ```
   *
   * Failure raises {@link TmuxCommandError} like any other command, carrying
   * tmux's own stderr.
   */
  cmd(
    command: string,
    args: readonly string[] = [],
    options?: CmdOptions,
  ): Promise<readonly string[]> {
    return runRawCommand(runtimeForServer(this), null, command, args, options);
  }
  /**
   * Run several tmux commands in order.
   *
   * The result is positional: `results[i]` holds what `commands[i]` printed,
   * empty for a command that prints nothing. Commands run as separate tmux
   * invocations because arbitrary command output has no alias-independent
   * delimiter.
   *
   * ```ts
   * const [[first], [second]] = await server.pipeline([
   *   ["new-window", "-d", "-P", "-F", "#{window_id}"],
   *   ["new-window", "-d", "-P", "-F", "#{window_id}"],
   * ]);
   * ```
   *
   * Not atomic. tmux runs the commands in order and stops at the first failure,
   * leaving everything before it applied; the error names the command that
   * failed. Take a {@link Server.snapshot} afterwards if you need to know what
   * survived.
   *
   */
  pipeline(
    commands: readonly (readonly string[])[],
    options?: CommandOptions,
  ): Promise<readonly (readonly string[])[]> {
    return runPipeline(runtimeForServer(this), commands, options);
  }

  /**
   * Run planned mutations in order, resolving each to what it made.
   *
   * The batched form of calling them one at a time: the same options go in and
   * the same handles come out, positionally and individually typed. Calling
   * `newWindow` repeatedly takes one snapshot after each mutation; a batch runs
   * the mutations in order and resolves all of them from one final snapshot.
   *
   * ```ts
   * const [editor, logs] = await server.batch([
   *   session.plan.newWindow({ name: "editor" }),
   *   session.plan.newWindow({ name: "logs" }),
   * ]);
   * ```
   *
   * Not atomic, for the same reason {@link Server.pipeline} is not: tmux runs
   * them in order and stops at the first failure, leaving everything before it
   * applied.
   */
  async batch<const T extends readonly PlannedOperation<unknown>[]>(
    operations: T,
    options?: CommandOptions,
  ): Promise<{
    -readonly [K in keyof T]: T[K] extends PlannedOperation<infer R> ? R : never;
  }> {
    const printed = await this.pipeline(
      operations.map((operation) => operation.argv),
      options,
    );
    // One snapshot for the whole group, taken after every command has run, so
    // each plan reads the same instant and the group costs one snapshot rather
    // than one per mutation. It carries the caller's signal: a batch abandoned
    // between its commands and this read is abandoned, and taking it
    // unsignalled left the handles resolving against a server the caller had
    // already stopped waiting for.
    const snapshot = await this.snapshot(
      options?.signal === undefined ? {} : { signal: options.signal },
    );
    return operations.map((operation, index) =>
      operation.resolve(snapshot, printed[index] ?? []),
    ) as { -readonly [K in keyof T]: T[K] extends PlannedOperation<infer R> ? R : never };
  }

  /**
   * Whether `other` is a handle addressing the same tmux server.
   *
   * Compared by the socket the connection resolves to rather than by object
   * identity, so a server constructed twice against one socket is equal to
   * itself. A socket *name* is not that socket: tmux resolves `-L work` under
   * `TMUX_TMPDIR`, so the same name with two different tmpdirs addresses two
   * different daemons, and this reports them as different. Accepts `unknown`
   * because the interesting comparisons are against values a caller has not
   * narrowed yet.
   *
   * ```ts
   * server.equals(new Server({ socketPath: server.socketPath ?? "" }));
   * ```
   */
  equals(other: unknown): boolean {
    const runtime = runtimeForServerValue(this);
    const otherRuntime = runtimeForServerValue(other);
    if (runtime === undefined || otherRuntime === undefined) return false;
    if (runtime === otherRuntime) return true;
    const address = serverAddress(runtime);
    return address !== undefined && address === serverAddress(otherRuntime);
  }
}

const runtimeConstructors: RuntimeConstructors = Object.freeze({
  client: Client.prototype,
  pane: Pane.prototype,
  server: Server.prototype,
  session: Session.prototype,
  window: Window.prototype,
});

