#!/usr/bin/env node
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { realpathSync } from "node:fs";
import { constants as osConstants } from "node:os";
import { isAbsolute } from "node:path";
import { pathToFileURL } from "node:url";

import { TmuxTransportError } from "libtmux/errors";
import { Server } from "libtmux/server";

import { readCallerEnvironment } from "./caller.js";
import { createContext } from "./context.js";
import { buildInstructions } from "./instructions.js";
import { resolvePolicy, snapshotPolicy, type Policy } from "./policy.js";
import { boundRequestIds } from "./protocol_transport.js";
import { assertKnownPolicyTools, ToolRegistry } from "./register.js";
import { assertSafeRouteValue } from "./route.js";
import { registerCapture } from "./tools/capture.js";
import { registerDiscovery } from "./tools/discovery.js";
import { registerInput } from "./tools/input.js";
import { registerPrograms } from "./tools/programs.js";
import { registerLayout } from "./tools/layout.js";
import { registerLifecycle } from "./tools/lifecycle.js";
import { registerSearch } from "./tools/search.js";
import { registerSettings } from "./tools/settings.js";
import { registerWait } from "./tools/wait.js";
import { registerTargetTools } from "./tools/target.js";
import { registerResources } from "./resources.js";
import {
  attachCommand,
  describeStartup,
  inspectServerStartup,
  type ServerStartup,
} from "./startup.js";

import manifest from "../package.json" with { type: "json" };

export type { Policy, Toolset } from "./policy.js";

/** The version this server reports, taken from the manifest so it cannot drift. */
const PACKAGE_VERSION: string = manifest.version;

/**
 * An MCP server exposing a tmux server through libtmux.
 *
 * Instructions are built at construction rather than at handshake because they
 * carry where this process is running, which cannot change while it runs.
 */
export function createTmuxMcpServer(
  tmux: Server,
  options: {
    /** Complete environment identifying the host process's tmux pane. */
    readonly callerEnvironment?: Readonly<Record<string, string | undefined>>;
    /** Complete environment from which to resolve MCP tool policy. */
    readonly environment?: Readonly<Record<string, string | undefined>>;
    readonly policy?: Policy;
    /** Socket state and configuration provenance pinned before registration. */
    readonly startup?: ServerStartup;
  } = {},
): McpServer {
  const caller = readCallerEnvironment(options.callerEnvironment ?? process.env);
  const startup: ServerStartup = Object.freeze(
    options.startup ?? {
      configurationProvenance: "unknown",
      serverState: "unprobed",
    },
  );
  const policy = snapshotPolicy(
    options.policy ?? resolvePolicy(options.environment ?? process.env),
  );
  const context = createContext(tmux, policy, caller);
  const catalog = new ToolRegistry();
  registerDiscovery(catalog, context);
  registerCapture(catalog, context);
  registerSearch(catalog, context);
  registerInput(catalog, context);
  const programs = registerPrograms(catalog, context);
  registerLifecycle(catalog, context);
  registerLayout(catalog, context);
  registerSettings(catalog, context);
  registerWait(catalog, context);
  registerTargetTools(catalog, context);
  const resolved = catalog.resolve(policy);

  // Resolution and validation finish before the SDK core exists, and before a
  // lazy libtmux Server has any reason to open its selected socket.
  const mcp = new McpServer(
    { name: "libtmux", title: "tmux", version: PACKAGE_VERSION },
    { instructions: buildInstructions(policy, caller, resolved.names) },
  );
  resolved.register(mcp);
  if (resolved.definitions.length === 0) {
    mcp.server.registerCapabilities({ tools: {} });
    mcp.server.setRequestHandler(ListToolsRequestSchema, () => ({ tools: [] }));
  }
  const socketSelector = context.route.selector;
  const selectionProvenance =
    context.route.socketPath !== undefined
      ? "socket-path"
      : context.route.socketName !== undefined
        ? "socket-name"
        : "tmux-choice";
  const disclosedSocketPath = startup.resolvedSocketPath ?? context.route.socketPath ?? null;
  const capabilityReport = Object.freeze({
    boundary: Object.freeze({
      dynamicResources: false,
      hostCommandExecution: false,
      oneSocketPerProcess: true,
      perCallSocketSelection: false,
    }),
    connection: Object.freeze({
      attachCommand: startup.attachCommand ?? attachCommand(tmux, disclosedSocketPath),
      configurationProvenance: startup.configurationProvenance,
      resolvedSocketPath: disclosedSocketPath,
      serverState: startup.serverState,
      socketProvenance: selectionProvenance,
      socketSelector,
    }),
    contractVersion: 1,
    executionAuthority: "tmux-user",
    excludeTools: Object.freeze([...policy.excludeTools].sort()),
    hostCommandTools: 0,
    frozen: true,
    operatingSystemBoundary: "none",
    schemaVersion: 1,
    selectedToolsets: Object.freeze([...policy.toolsets].sort()),
    socket: Object.freeze({
      configurationProvenance: startup.configurationProvenance,
      namespaceBoundary: "tmux-objects-only",
      selectionProvenance,
      selector: socketSelector,
      serverState: startup.serverState,
    }),
    toolCount: resolved.definitions.length,
    toolFilteringBoundary: "interface-shaping-not-authorization",
    ...resolved.report(),
  });
  const disposeResources = registerResources(mcp, capabilityReport);

  let backendClose: Promise<void> | undefined;
  const closeBackend = (): Promise<void> => {
    backendClose ??= (async () => {
      try {
        await programs.close();
        await disposeResources();
      } finally {
        await context.close();
      }
    })();
    return backendClose;
  };
  mcp.server.onclose = (): void => {
    void closeBackend().catch(() => undefined);
  };

  // The protocol close callback is synchronous. Embedded callers still need
  // `close()` to mean every control process has actually left.
  const closeProtocol = mcp.close.bind(mcp);
  let serverClose: Promise<void> | undefined;
  mcp.close = (): Promise<void> => {
    serverClose ??= closeProtocol().then(
      () => closeBackend(),
      async (error: unknown) => {
        await closeBackend();
        throw error;
      },
    );
    return serverClose;
  };

  return mcp;
}

/**
 * The tmux server this process was pointed at.
 *
 * An MCP client launches this with an environment and a command line, and
 * nothing else, so the environment is the only place a socket can come from.
 * The library reads `LIBTMUX_SOCKET_PATH`, else `LIBTMUX_SOCKET`, from it; with
 * neither set no socket is passed and tmux picks the server, which inside tmux
 * is the one `TMUX` names. What the library chose is checked here, at the edge
 * that has a process to answer for it.
 */
export function serverFromEnvironment(
  environment: Readonly<Record<string, string | undefined>> = process.env,
): Server {
  if (Object.prototype.hasOwnProperty.call(environment, "LIBTMUX_SOCKET_NAME")) {
    throw new TypeError("LIBTMUX_SOCKET_NAME is retired; use LIBTMUX_SOCKET");
  }
  const tmuxBin = environment.LIBTMUX_TMUX_BIN;
  const policy = resolvePolicy(environment);
  assertKnownPolicyTools(policy);
  assertSafeRouteValue(
    "LIBTMUX_TMUX_BIN",
    tmuxBin === undefined || tmuxBin === "" ? "tmux" : tmuxBin,
  );
  const configFile = environment.LIBTMUX_TMUX_CONFIG;
  if (configFile !== undefined && !isAbsolute(configFile)) {
    throw new TypeError("LIBTMUX_TMUX_CONFIG must be a nonempty absolute path");
  }
  const server = new Server({
    // Bounded here rather than in the library: this process answers a client
    // that is waiting, so "wait as long as tmux takes" is not an option it has.
    timeoutMs: policy.commandTimeoutMs,
    ...(configFile === undefined ? {} : { configFile }),
    environment,
    ...(tmuxBin === undefined || tmuxBin === "" ? {} : { tmuxBin }),
  });
  if (server.socketPath !== undefined) {
    assertSafeRouteValue("LIBTMUX_SOCKET_PATH", server.socketPath);
    if (!isAbsolute(server.socketPath)) {
      throw new TypeError("LIBTMUX_SOCKET_PATH must be absolute");
    }
  } else if (server.socketName !== undefined) {
    assertSafeRouteValue("LIBTMUX_SOCKET", server.socketName);
  }
  return server;
}

/** Serve until stdin or the protocol closes, then join the backend. */
export async function main(): Promise<void> {
  // Resolved once and handed to both, so the line cannot describe a policy
  // other than the one the tools were registered under.
  const tmux = serverFromEnvironment(process.env);
  const startup = await inspectServerStartup(tmux, process.env);
  const policy = resolvePolicy(process.env);
  const mcp = createTmuxMcpServer(tmux, { policy, startup });
  // stderr, because stdout is the protocol: a byte written there that is not
  // a JSON-RPC frame ends the session. Once, before serving, so a later
  // question about which tmux this process chose and how much it was allowed
  // to do has an answer that does not depend on reproducing the launch.
  process.stderr.write(
    `${describeStartup({
      caller: readCallerEnvironment(),
      environment: process.env,
      policy,
      server: tmux,
      serverState: startup.serverState,
      version: PACKAGE_VERSION,
    })}\n`,
  );
  const closed = Promise.withResolvers<void>();
  const onClose = mcp.server.onclose;
  mcp.server.onclose = (): void => {
    onClose?.();
    closed.resolve();
  };
  const onEnd = (): void => {
    closed.resolve();
  };
  // A signal shuts down as stdin's end does and exits with that signal's status;
  // a second signal kills at once.
  const signals = ["SIGHUP", "SIGINT", "SIGTERM"] as const;
  const stopHandling = (): void => {
    for (const signal of signals) process.off(signal, onSignal);
  };
  const onSignal = (signal: NodeJS.Signals): void => {
    stopHandling();
    process.exitCode = 128 + osConstants.signals[signal];
    closed.resolve();
  };
  process.stdin.once("end", onEnd);
  for (const signal of signals) process.on(signal, onSignal);
  try {
    await mcp.connect(boundRequestIds(new StdioServerTransport()));
    if (!process.stdin.readableEnded && !process.stdin.destroyed) await closed.promise;
  } finally {
    process.stdin.off("end", onEnd);
    stopHandling();
    await mcp.close();
  }
}

/**
 * Run when this file is the program, not when it is imported.
 *
 * Compared by URL rather than by `import.meta.main`, which Node does not have,
 * so the same file serves under both runtimes.
 *
 * Through the real path on both sides, because npm installs a `bin` as a
 * symlink: invoked that way `process.argv[1]` is the link and `import.meta.url`
 * is what it points at, so comparing them raw is always false and the server
 * exits without serving. Silently, and with status 0 — a client sees a server
 * that starts and offers nothing.
 */
function isProgram(entry: string | undefined): boolean {
  if (entry === undefined) return false;
  if (import.meta.url === pathToFileURL(entry).href) return true;
  try {
    return import.meta.url === pathToFileURL(realpathSync(entry)).href;
  } catch {
    return false;
  }
}

/**
 * One actionable line for a failure that happened before serving began.
 *
 * stdout is the protocol, so stderr is the whole diagnostic channel, and an MCP
 * client surfaces it as the reason a server would not start. `spawn`/`ENOENT`
 * is separated because Node reports it as `spawn tmux ENOENT`, which reads as
 * tmux refusing rather than tmux being absent.
 */
export function describeStartupFailure(
  error: unknown,
  environment: Readonly<Record<string, string | undefined>> = process.env,
): string {
  if (error instanceof TmuxTransportError && error.kind === "spawn") {
    const cause: unknown = error.cause;
    const code =
      typeof cause === "object" && cause !== null && "code" in cause
        ? (cause as { readonly code?: unknown }).code
        : undefined;
    if (code === "ENOENT") {
      const configured = environment.LIBTMUX_TMUX_BIN;
      const named = configured === undefined || configured === "" ? "tmux" : configured;
      return `cannot execute ${named}: install tmux, or set LIBTMUX_TMUX_BIN to its path`;
    }
  }
  return error instanceof Error ? error.message : String(error);
}

if (isProgram(process.argv[1])) {
  try {
    await main();
  } catch (error) {
    process.stderr.write(`libtmux-mcp: ${describeStartupFailure(error)}\n`);
    process.exitCode = 1;
  }
}

packages/mcp/src/startup.ts.content:
/**
 * What this process decided before it started answering.
 *
 * An MCP server is configured entirely by the environment its client hands it,
 * which means every misconfiguration is silent by construction: the operator
 * who meant `inspect` and wrote `inspection` sees a server that starts, lists
 * tools, and works. Saying the effective policy once, out loud, is what turns
 * that into something a person can notice.
 */

import { TmuxTransportError } from "libtmux/errors";
import type { Server } from "libtmux/server";
import { isAbsolute, join } from "node:path";

import type { CallerEnvironment } from "./caller.js";
import type { Policy } from "./policy.js";

export interface StartupFacts {
  readonly caller: CallerEnvironment;
  /** The environment tmux followed when it was given no socket; the process's by default. */
  readonly environment?: Readonly<Record<string, string | undefined>>;
  readonly policy: Policy;
  readonly server: Server;
  /** Whether a tmux server was already running on that socket. */
  readonly serverState: ServerState;
  readonly version: string;
}

export type ConfigurationProvenance = "unknown" | "user-configured";
export type ServerState = "absent" | "existing" | "unprobed";

/** Socket facts observed once, before the MCP surface is exposed. */
export interface ServerStartup {
  readonly attachCommand?: string;
  readonly configurationProvenance: ConfigurationProvenance;
  readonly resolvedSocketPath?: string | null;
  readonly serverState: ServerState;
}

/** Single-quote a value for POSIX shell, escaping any embedded `'`. */
export function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'"'"'`)}'`;
}

/**
 * The socket path tmux takes from `TMUX` when it is given no socket.
 *
 * tmux reads everything before the first comma, so a path holding one is cut
 * there, and a value that is not absolute names nothing.
 */
export function socketFromTmuxVariable(
  environment: Readonly<Record<string, string | undefined>>,
): string | undefined {
  const [path] = (environment.TMUX ?? "").split(",");
  return path !== undefined && isAbsolute(path) ? path : undefined;
}

/** Resolve the socket tmux would use without starting a daemon. */
export function resolvedSocketPath(
  server: Server,
  environment: Readonly<Record<string, string | undefined>> = process.env,
): string | null {
  if (server.socketPath !== undefined) return server.socketPath;
  if (server.socketName === undefined) {
    const current = socketFromTmuxVariable(environment);
    if (current !== undefined) return current;
  }
  const uid = process.getuid?.();
  if (uid === undefined) return null;
  const base = environment.TMUX_TMPDIR;
  return join(
    base === undefined || base === "" ? "/tmp" : base,
    `tmux-${String(uid)}`,
    server.socketName ?? "default",
  );
}

/** A shell-safe observer command that refuses to create an absent server. */
export function attachCommand(server: Server, socketPath: string | null): string {
  const selector =
    socketPath === null
      ? `-L ${shellQuote(server.socketName ?? "default")}`
      : `-S ${shellQuote(socketPath)}`;
  return `${shellQuote(server.tmuxBin)} -N ${selector} attach`;
}

/**
 * Pin the startup facts used for policy and reporting.
 *
 * An already-running daemon may have been started by anybody, so its
 * configuration is unknown. One that is absent gets whatever configuration tmux
 * loads when something starts it, which is the user's own.
 */
export async function inspectServerStartup(
  server: Server,
  environment: Readonly<Record<string, string | undefined>> = process.env,
): Promise<ServerStartup> {
  const selectedPath = resolvedSocketPath(server, environment);
  if (await server.isAlive()) {
    let observedPath = selectedPath;
    try {
      const lines = await server.cmd("display-message", ["-p", "#{socket_path}"], {
        target: null,
      });
      if (lines[0] !== undefined && lines[0] !== "") observedPath = lines[0];
    } catch {
      // The daemon can exit between the no-start probe and this disclosure read.
    }
    return Object.freeze({
      attachCommand: attachCommand(server, observedPath),
      configurationProvenance: "unknown",
      resolvedSocketPath: observedPath,
      serverState: "existing",
    });
  }
  // An empty socket is a fact about the server. A tmux that cannot run at all is
  // a fact about this launch, and ends it with the executable named.
  await server.checkAlive().catch((error: unknown) => {
    if (error instanceof TmuxTransportError && error.kind === "spawn") throw error;
  });
  return Object.freeze({
    attachCommand: attachCommand(server, selectedPath),
    configurationProvenance: "user-configured",
    resolvedSocketPath: selectedPath,
    serverState: "absent",
  });
}

/**
 * The socket this server addresses, as an operator wrote it, or the one tmux
 * picked: the socket `TMUX` names inside tmux, otherwise `default`.
 */
function socketOf(
  server: Server,
  environment: Readonly<Record<string, string | undefined>>,
): string {
  return server.socketPath ?? server.socketName ?? socketFromTmuxVariable(environment) ?? "default";
}

/**
 * Whether a tmux server was already on the socket, which is the only notice
 * that an agent is sharing a daemon with whoever else is on it.
 */
const REACHED: Readonly<Record<ServerState, string>> = Object.freeze({
  absent: "serving",
  existing: "serving existing",
  unprobed: "serving",
});

/**
 * One line naming the authority this process is running with.
 *
 * Everything here answers a question somebody asks *after* something went
 * wrong: which tmux did it choose, had somebody else already started it, how
 * much was it allowed to do, and is it the pane I am typing in. A pane id means
 * nothing without its server, so the pane is named with the socket it lives on.
 */
export function describeStartup(facts: StartupFacts): string {
  const { caller, policy, server, serverState, version } = facts;
  const toolsets = [...policy.toolsets].sort().join(",") || "none";
  const narrowed = `, toolsets ${toolsets}, ${String(policy.tools.size)} named inclusions, ${String(policy.excludeTools.size)} exclusions`;
  const pane =
    caller.paneId === undefined
      ? ""
      : `, from pane ${caller.paneId}${caller.socketPath === undefined ? "" : ` on ${caller.socketPath}`}`;
  return `libtmux-mcp ${version} ${REACHED[serverState]} ${socketOf(server, facts.environment ?? process.env)}${narrowed}${pane}`;
}

packages/workspace/src/builder.ts.content:
import type { AbortLike } from "libtmux";
import type { Server } from "libtmux/server";
import type { Session } from "libtmux/session";
import type { Window } from "libtmux/window";
import {
  initialPaneStartDirectory,
  optionValue,
  paneCommands,
  paneStartDirectory,
  paneWantsFocus,
  parseWorkspace,
  windowStartDirectory,
  type Workspace,
  type WorkspaceInput,
  type WorkspaceWindow,
} from "./config.js";
import {
  normalizeApplyWorkspaceOptions,
  normalizePlanWorkspaceOptions,
  type ApplyWorkspaceOptions,
  type CommandPolicy,
  type PlanWorkspaceOptions,
} from "./operation_options.js";
import { claimSession, mayPrune, ownedByWorkspace } from "./ownership.js";
import {
  planWorkspace as createWorkspacePlan,
  runningSession,
  windowIsShared,
  type WorkspacePlan,
} from "./planning.js";

export type {
  WorkspacePaneCreation,
  WorkspacePaneRemoval,
  WorkspacePlan,
  WorkspaceRetention,
  WorkspaceWindowCreation,
  WorkspaceWindowPlacement,
  WorkspaceWindowRemoval,
  WorkspaceWindowRename,
} from "./planning.js";
export type {
  ApplyWorkspaceOptions,
  CommandPolicy,
  PlanWorkspaceOptions,
} from "./operation_options.js";

/**
 * `AbortLike` is structural and does not guarantee `throwIfAborted`, so an
 * already-fired signal is checked by hand at each loop boundary between tmux
 * calls. Every call this module makes that accepts `{ signal }` still gets it
 * directly; this only covers the gap between two such calls.
 */
function throwIfAborted(signal: AbortLike | undefined): void {
  if (signal?.aborted) throw new DOMException("The operation was aborted.", "AbortError");
}

/** A high-level apply operation that finished before a later one failed. */
export type WorkspaceApplyMilestone =
  | { readonly kind: "session"; readonly status: "created" | "existing" }
  | { readonly kind: "session-claimed" }
  | { readonly kind: "workspace-option"; readonly name: string }
  | { readonly index: number; readonly kind: "window" }
  | { readonly kind: "windows-reconciled" };

/** The high-level operation an apply was attempting when it failed. */
export type WorkspaceApplyStage =
  | {
      readonly action: "claim" | "create" | "lookup" | "ownership" | "result" | "snapshot";
      readonly kind: "session";
    }
  | { readonly kind: "workspace-option"; readonly name: string }
  | { readonly index: number; readonly kind: "window" }
  | { readonly kind: "windows-reconcile" }
  | { readonly kind: "focus" };

/**
 * Applying stopped after tmux may already have changed.
 *
 * `completed` records whole high-level milestones. The failed stage itself may
 * be partial because mutations are not transactions and transport failure may
 * leave delivery indeterminate. `requiresReplan` asks callers to rediscover
 * session, window, and pane structure; it says nothing about command effects.
 */
export class WorkspaceApplyError extends Error {
  readonly completed: readonly WorkspaceApplyMilestone[];
  readonly failed: WorkspaceApplyStage;
  readonly requiresReplan = true;

  constructor(
    workspace: string,
    completed: readonly WorkspaceApplyMilestone[],
    failed: WorkspaceApplyStage,
    cause: unknown,
  ) {
    super(`workspace ${workspace} failed during ${failed.kind}`, { cause });
    this.name = "WorkspaceApplyError";
    this.completed = Object.freeze(
      completed.map((milestone) => Object.freeze({ ...milestone } as WorkspaceApplyMilestone)),
    );
    this.failed = Object.freeze({ ...failed } as WorkspaceApplyStage);
  }
}

/**
 * Build a workspace into a real tmux session, or reconcile one that exists.
 *
 * tmux gives every new session a window and every new window a pane, so the
 * first window and first pane of each level are adopted rather than created.
 * Creating them anyway is the classic workspace-builder bug that leaves an
 * empty leading window behind.
 *
 * What this reconciles is *topology*: which windows exist, in what order, under
 * what names, with how many panes, under which layout. It is safe to apply
 * twice and the second run does not duplicate anything. It is deliberately not
 * a process supervisor — see {@link CommandPolicy} — and it does not unset
 * options a previous version of the file had set, because tmux cannot say which
 * of an option's current values this file is responsible for.
 *
 * This is not the builder behind the `tmux-workspace` command. The two are
 * separate implementations of one idea and they answer differently: this one
 * converges a session that exists, while the CLI compares it against the
 * document and refuses when they disagree. The document language differs too —
 * the schema here is strict, so `environment`, `before_script`, `window_index`,
 * `suppress_history`, `x-` keys and the CLI's other fields are rejected. A file
 * written for the CLI is not necessarily one this accepts.
 *
 * @throws ZodError when the workspace does not satisfy the strict config schema.
 * @throws TypeError when operation options, layouts or version replies are invalid.
 * @throws WorkspaceApplyError when tmux fails after applying may have started.
 */
export async function applyWorkspace(
  server: Server,
  workspaceInput: WorkspaceInput,
  options: ApplyWorkspaceOptions = {},
): Promise<Session> {
  const workspace = parseWorkspace(workspaceInput);
  const { commands, prune, signal } = normalizeApplyWorkspaceOptions(options);
  const acquisition = signal ? { signal } : {};
  await server.validateLayouts(
    workspace.windows.flatMap((window) =>
      window.layout ? [{ layout: window.layout, panes: window.panes.length }] : [],
    ),
    acquisition,
  );
  const completed: WorkspaceApplyMilestone[] = [];
  let failed: WorkspaceApplyStage = { action: "lookup", kind: "session" };
  try {
    const existing = await runningSession(server, workspace.session_name, acquisition);
    failed = { action: "create", kind: "session" };
    const created = existing ?? (await createSession(server, workspace, acquisition));
    completed.push({ kind: "session", status: existing === undefined ? "created" : "existing" });

    // Stamped on the session this apply created, and read back on every later
    // one. A name is a lookup, not a claim: without the mark, converging a
    // hand-made session of the same name would kill windows nobody described.
    failed = { action: "ownership", kind: "session" };
    const owned =
      existing === undefined ||
      (await ownedByWorkspace(existing, workspace.session_name, acquisition));
    if (existing === undefined) {
      failed = { action: "claim", kind: "session" };
      await claimSession(created, workspace.session_name, acquisition);
      completed.push({ kind: "session-claimed" });
    }
    const pruning = mayPrune(prune, owned);

    failed = { action: "snapshot", kind: "session" };
    let session = (await server.snapshot(acquisition)).sessions.one({ id: created.id });

    for (const [option, value] of Object.entries(workspace.options ?? {})) {
      failed = { kind: "workspace-option", name: option };
      // eslint-disable-next-line no-await-in-loop -- Later options may depend on earlier ones.
      await session.setOption(option, optionValue(value), acquisition);
      completed.push({ kind: "workspace-option", name: option });
    }

    for (const [index, desired] of workspace.windows.entries()) {
      failed = { index, kind: "window" };
      throwIfAborted(signal);
      // Session.refreshed() re-reads the server but takes no options yet, so
      // this call itself cannot be cancelled; the check above still catches an
      // abort that fired between windows.
      // eslint-disable-next-line no-await-in-loop -- Window order is observable, so creation is sequential.
      session = await session.refreshed();
      // A session created for this workspace had its first window made by tmux,
      // so that window is this apply's too, and its panes take the commands.
      const born = existing === undefined && index === 0;
      // eslint-disable-next-line no-await-in-loop -- Window order is observable, so creation is sequential.
      const placed = await windowAt(session, index, desired, workspace, acquisition);
      // eslint-disable-next-line no-await-in-loop -- Window order is observable, so creation is sequential.
      await applyWindow(placed.window, desired, workspace, {
        commands,
        pruning,
        signal,
        windowIsNew: placed.created || born,
      });
      completed.push({ index, kind: "window" });
    }

    if (pruning) {
      failed = { kind: "windows-reconcile" };
      session = await pruneWindows(session, workspace.windows.length, acquisition);
      completed.push({ kind: "windows-reconciled" });
    }
    failed = { kind: "focus" };
    await focusRequested(session, workspace, acquisition);
    failed = { action: "result", kind: "session" };
    return (await server.snapshot(acquisition)).sessions.one({ id: created.id });
  } catch (error) {
    throw new WorkspaceApplyError(workspace.session_name, completed, failed, error);
  }
}

/**
 * Plan session, window, and pane membership without changing tmux.
 *
 * Reads the server once and answers from that capture, so it costs one snapshot
 * and changes nothing. It reports structural creation, removal, retention, and
 * window renames. It does not predict options, layouts, focus, or pane command
 * effects.
 *
 * ```ts
 * const plan = await planWorkspace(server, workspace);
 * if (plan.removesWindows.length > 0) console.log("would remove", plan.removesWindows);
 * ```
 *
 * @throws ZodError when the workspace does not satisfy the strict config schema.
 * @throws TypeError when planning options are invalid.
 */
export async function planWorkspace(
  server: Server,
  workspaceInput: WorkspaceInput,
  options: PlanWorkspaceOptions = {},
): Promise<WorkspacePlan> {
  const workspace = parseWorkspace(workspaceInput);
  const { prune, signal } = normalizePlanWorkspaceOptions(options);
  return createWorkspacePlan(server, workspace, prune, signal ? { signal } : {});
}

async function createSession(
  server: Server,
  workspace: Workspace,
  acquisition: { signal?: AbortLike },
): Promise<Session> {
  const directory = initialPaneStartDirectory(workspace);
  return server.newSession({
    name: workspace.session_name,
    ...(directory === undefined ? {} : { startDirectory: directory }),
    ...(workspace.windows[0]?.window_name === undefined
      ? {}
      : { windowName: workspace.windows[0].window_name }),
    ...acquisition,
  });
}

/**
 * The window that should hold position `index`, created if it is not there yet.
 *
 * tmux window indexes are not positions — `base-index` shifts them and a killed
 * window leaves a gap — so position is resolved by ordinal, not by index.
 */
async function windowAt(
  session: Session,
  index: number,
  desired: WorkspaceWindow,
  workspace: Workspace,
  acquisition: { signal?: AbortLike },
): Promise<{ readonly created: boolean; readonly window: Window }> {
  const existing = session.windows.at(index);
  if (existing === undefined) {
    const firstPane = desired.panes[0];
    const directory =
      firstPane === undefined
        ? windowStartDirectory(desired, workspace)
        : paneStartDirectory(firstPane, desired, workspace);
    return {
      created: true,
      window: await session.newWindow({
        ...(desired.window_name === undefined ? {} : { name: desired.window_name }),
        ...(directory === undefined ? {} : { startDirectory: directory }),
        ...acquisition,
      }),
    };
  }
  if (desired.window_name !== undefined && existing.name !== desired.window_name) {
    await existing.rename(desired.window_name);
    return { created: false, window: await existing.refreshed() };
  }
  return { created: false, window: existing };
}

/**
 * What applying one window needs to know beyond the window itself.
 *
 * `windowIsNew` separates the two jobs this does: a window it just created
 * needs everything set, and one that already existed needs only the
 * differences, so the flag is what keeps a rebuild from redoing the work.
 */
interface ApplyWindowContext {
  readonly commands: CommandPolicy;
  readonly pruning: boolean;
  readonly signal: AbortLike | undefined;
  readonly windowIsNew: boolean;
}

async function applyWindow(
  window: Window,
  desired: WorkspaceWindow,
  workspace: Workspace,
  context: ApplyWindowContext,
): Promise<void> {
  const acquisition = context.signal ? { signal: context.signal } : {};
  for (const [option, value] of Object.entries(desired.options ?? {})) {
    // eslint-disable-next-line no-await-in-loop -- Later options may depend on earlier ones.
    await window.setOption(option, optionValue(value), acquisition);
  }

  const wanted = desired.panes.length;
  let current = await window.refreshed();
  // The surplus set is known before any pane goes, so one final snapshot can
  // resolve all removals.
  const surplus =
    context.pruning && !windowIsShared(current) ? current.panes.toArray().slice(wanted) : [];
  if (surplus.length > 0) {
    await current.server.batch(
      surplus.map((pane) => pane.plan.killIfWindowUnshared()),
      acquisition,
    );
    current = await current.refreshed();
  }
  // Halving one pane in turn runs out of room by the fifth at a default 80x24,
  // where tmux answers "no space for a new pane", so the window is rebalanced
  // between splits. `desired.layout` below still has the final say, and a
  // batch cannot interleave the layout pass.
  const present = current.panes.length;
  for (let offset = 0; present + offset < wanted; offset += 1) {
    throwIfAborted(context.signal);
    const entry = desired.panes[present + offset];
    const directory =
      entry === undefined ? undefined : paneStartDirectory(entry, desired, workspace);
    // eslint-disable-next-line no-await-in-loop -- Each split needs the room the last one left.
    await current.split({
      ...(directory === undefined ? {} : { startDirectory: directory }),
      ...acquisition,
    });
    // eslint-disable-next-line no-await-in-loop -- The layout pass is what reclaims the room.
    await current.selectLayout("tiled");
  }
  if (present < wanted) current = await current.refreshed();

  // Panes at or past the count this apply found are the ones it just split; a
  // window it created has no older panes at all.
  const firstNewPane = context.windowIsNew ? 0 : present;
  for (const [index, entry] of desired.panes.entries()) {
    if (context.commands === "create-only" && index < firstNewPane) continue;
    throwIfAborted(context.signal);
    const pane = current.panes.at(index);
    if (pane === undefined) throw new Error(`window ${current.name} lost pane ${String(index)}`);
    for (const command of paneCommands(entry, desired)) {
      // eslint-disable-next-line no-await-in-loop -- Commands run in the order written.
      await pane.sendKeys(command, { literal: true, ...acquisition });
    }
  }

  // Layout requires the final pane count and stays last so its failure cannot
  // strand new panes before create-only command delivery.
  if (desired.layout) await current.selectLayout(desired.layout);
}

async function pruneWindows(
  session: Session,
  wanted: number,
  acquisition: { signal?: AbortLike },
): Promise<Session> {
  const current = await session.refreshed();
  if (current.grouped !== false) return current;
  const surplus = current.windows.toArray().slice(wanted);
  if (surplus.length === 0) return current;
  await current.server.batch(
    surplus.map((window) => window.plan.removePlacement()),
    acquisition,
  );
  return current.refreshed();
}

async function focusRequested(
  session: Session,
  workspace: Workspace,
  acquisition: { signal?: AbortLike },
): Promise<void> {
  throwIfAborted(acquisition.signal);
  const current = await session.refreshed();
  for (const [index, desired] of workspace.windows.entries()) {
    const window = current.windows.at(index);
    if (window === undefined) continue;
    const paneIndex = desired.panes.findIndex((entry) => paneWantsFocus(entry));
    if (paneIndex >= 0) {
      const pane = window.panes.at(paneIndex);
      // eslint-disable-next-line no-await-in-loop -- Selection is ordered; the last one wins.
      if (pane !== undefined) await pane.select();
    }
    // eslint-disable-next-line no-await-in-loop -- Selection is ordered; the last one wins.
    if (desired.focus === true) await window.select();
  }
}

