import { workspaceSchema } from "./schema.js";

/** A value tmux stores for a session or window option. */
export type WorkspaceOptionValue = string | number | boolean;

/** A pane: a bare command string, or the settings the pane is created with. */
export type WorkspacePane =
  | string
  | {
      focus?: boolean | undefined;
      shell_command?: string | string[] | undefined;
      start_directory?: string | undefined;
    };

/** A window with every schema default applied. */
export type WorkspaceWindow = {
  focus?: boolean | undefined;
  layout?: string | undefined;
  options?: Record<string, WorkspaceOptionValue> | undefined;
  panes: WorkspacePane[];
  shell_command_before?: string | string[] | undefined;
  start_directory?: string | undefined;
  window_name?: string | undefined;
};

/** A window as written, before `panes` defaults to one implicit pane. */
export type WorkspaceWindowInput = {
  focus?: boolean | undefined;
  layout?: string | undefined;
  options?: Record<string, WorkspaceOptionValue> | undefined;
  panes?: WorkspacePane[] | undefined;
  shell_command_before?: string | string[] | undefined;
  start_directory?: string | undefined;
  window_name?: string | undefined;
};

/** A validated workspace with every schema default and transform applied. */
export type Workspace = {
  options?: Record<string, WorkspaceOptionValue> | undefined;
  session_name: string;
  start_directory?: string | undefined;
  windows: WorkspaceWindow[];
};

/** Workspace data before schema defaults and transforms are applied. */
export type WorkspaceInput = {
  options?: Record<string, WorkspaceOptionValue> | undefined;
  session_name: string;
  start_directory?: string | undefined;
  windows: WorkspaceWindowInput[];
};

/** Validate a parsed workspace, rejecting anything the schema does not allow. */
export function parseWorkspace(value: unknown): Workspace {
  return workspaceSchema.parse(value);
}

/**
 * Parse a YAML or JSON workspace, then validate it.
 *
 * YAML parsing is Bun's, and this package otherwise runs anywhere — so this is
 * the one function that does not. Reached from Node it says so, rather than
 * failing on an undefined global; parse the document yourself and hand the
 * result to {@link parseWorkspace}.
 */
export function parseWorkspaceYaml(source: string): Workspace {
  const yaml = (globalThis as { Bun?: { YAML?: { parse: (source: string) => unknown } } }).Bun
    ?.YAML;
  if (yaml === undefined) {
    throw new Error(
      "parseWorkspaceYaml needs Bun's YAML parser; parse the document yourself and use parseWorkspace",
    );
  }
  return parseWorkspace(yaml.parse(source));
}

function asCommands(value: string | readonly string[] | undefined): readonly string[] {
  if (value === undefined) return [];
  return typeof value === "string" ? [value] : value;
}

/**
 * Normalize a pane entry to the commands it should run, in order.
 *
 * A window's `shell_command_before` runs in every one of its panes, ahead of
 * that pane's own commands, which is how tmuxp seeds a common environment.
 */
export function paneCommands(pane: WorkspacePane, window?: WorkspaceWindow): readonly string[] {
  const own = typeof pane === "string" ? [pane] : asCommands(pane.shell_command);
  return [...asCommands(window?.shell_command_before), ...own].filter(
    (command) => command.length > 0,
  );
}

/** Whether a pane entry asked to be the focused one. */
export function paneWantsFocus(pane: WorkspacePane): boolean {
  return typeof pane !== "string" && pane.focus === true;
}

/** A pane's start directory, falling back to its window's and then the session's. */
export function paneStartDirectory(
  pane: WorkspacePane,
  window: WorkspaceWindow,
  workspace: Workspace,
): string | undefined {
  if (typeof pane !== "string" && pane.start_directory !== undefined) return pane.start_directory;
  return window.start_directory ?? workspace.start_directory;
}

/** A window's directory, inherited from its workspace when it has none. */
export function windowStartDirectory(
  window: WorkspaceWindow,
  workspace: Workspace,
): string | undefined {
  return window.start_directory ?? workspace.start_directory;
}

/** The directory tmux needs when it creates the session's first pane. */
export function initialPaneStartDirectory(workspace: Workspace): string | undefined {
  const window = workspace.windows[0];
  if (window === undefined) return workspace.start_directory;
  const pane = window.panes[0];
  return pane === undefined
    ? windowStartDirectory(window, workspace)
    : paneStartDirectory(pane, window, workspace);
}

/** Convert a YAML scalar to the string tmux accepts for an option value. */
export function optionValue(value: WorkspaceOptionValue): string {
  if (typeof value === "boolean") return value ? "on" : "off";
  return String(value);
}

packages/workspace/src/operation_options.content:
import type { AbortLike } from "libtmux";
import type { PrunePolicy } from "./ownership.js";

/**
 * When a pane's `shell_command` entries are sent to it.
 *
 * `create-only`, the default, sends them only to panes this apply created.
 * `always` sends them to every pane on every apply.
 */
export type CommandPolicy = "always" | "create-only";

/** How `applyWorkspace` should treat a workspace that is already running. */
export interface ApplyWorkspaceOptions {
  readonly commands?: CommandPolicy;
  /** How this apply treats undescribed topology; `always` does not claim ownership. */
  readonly prune?: PrunePolicy;
  /** Abandon the apply when this signal fires. A build already begun is not rolled back. */
  readonly signal?: AbortLike;
}

/** Structural planning options; pane command delivery is apply-only. */
export interface PlanWorkspaceOptions {
  /** How this plan treats undescribed topology; `always` does not claim ownership. */
  readonly prune?: PrunePolicy;
  /** Abandon the plan when this signal fires. Planning changes nothing, so there is nothing to unwind. */
  readonly signal?: AbortLike;
}

/** Validate and snapshot apply options before server access. */
export function normalizeApplyWorkspaceOptions(options: ApplyWorkspaceOptions): {
  readonly commands: CommandPolicy;
  readonly prune: PrunePolicy;
  readonly signal: AbortLike | undefined;
} {
  assertOptionBag(options, "applyWorkspace");
  for (const name of Reflect.ownKeys(options)) {
    if (name !== "commands" && name !== "prune" && name !== "signal") {
      throw new TypeError(`applyWorkspace does not accept option ${String(name)}`);
    }
  }
  const commands = Object.hasOwn(options, "commands") ? options.commands : undefined;
  const prune = Object.hasOwn(options, "prune") ? options.prune : undefined;
  return { commands: commandPolicy(commands), prune: prunePolicy(prune), signal: options.signal };
}

/** Validate and snapshot planning options before server access. */
export function normalizePlanWorkspaceOptions(options: PlanWorkspaceOptions): {
  readonly prune: PrunePolicy;
  readonly signal: AbortLike | undefined;
} {
  assertOptionBag(options, "planWorkspace");
  if (Object.hasOwn(options, "commands")) {
    throw new TypeError("planWorkspace does not plan pane command delivery");
  }
  for (const name of Reflect.ownKeys(options)) {
    if (name !== "prune" && name !== "signal") {
      throw new TypeError(`planWorkspace does not accept option ${String(name)}`);
    }
  }
  const prune = Object.hasOwn(options, "prune") ? options.prune : undefined;
  return { prune: prunePolicy(prune), signal: options.signal };
}

function assertOptionBag(value: unknown, method: string): asserts value is object {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${method} options must be a plain object`);
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError(`${method} options must be a plain object`);
  }
}

function commandPolicy(value: unknown): CommandPolicy {
  if (value !== undefined && value !== "always" && value !== "create-only") {
    throw new TypeError('workspace commands must be "always" or "create-only"');
  }
  return value ?? "create-only";
}

function prunePolicy(value: unknown): PrunePolicy {
  if (value !== undefined && value !== "always" && value !== "never" && value !== "owned") {
    throw new TypeError('workspace prune must be "always", "never", or "owned"');
  }
  return value ?? "owned";
}

packages/workspace/src/ownership.ts.content:
import type { AbortLike } from "libtmux";
import type { Session } from "libtmux/session";

/**
 * Which sessions this package may take things away from.
 *
 * A workspace finds its session by name, and a name is not a claim: `dev` in a
 * config file and `dev` a person started by hand are the same lookup, and
 * converging the second means killing windows nobody described. So creating a
 * session marks it, and pruning asks the mark rather than the name.
 *
 * The mark is a tmux user option on the session, which is where it has to live:
 * it must survive this process exiting, be readable by whatever runs next, and
 * disappear with the session it describes. Nothing else on the server has that
 * lifetime.
 */

/** The option a workspace stamps on the sessions it created. */
export const OWNERSHIP_OPTION = "@libtmux-workspace";

/** What to do with windows and panes the workspace does not describe. */
export type PrunePolicy = "always" | "never" | "owned";

/** Whether this session carries the mark for `name`. */
export async function ownedByWorkspace(
  session: Session,
  name: string,
  acquisition: { signal?: AbortLike } = {},
): Promise<boolean> {
  const options = await session.showOptions(acquisition);
  return options.get(OWNERSHIP_OPTION) === name;
}

/** Claim a session this apply created. */
export async function claimSession(
  session: Session,
  name: string,
  acquisition: { signal?: AbortLike } = {},
): Promise<void> {
  await session.setOption(OWNERSHIP_OPTION, name, acquisition);
}

/**
 * Whether surplus topology may be removed.
 *
 * `owned` is the default because it is the only one that is safe without
 * knowing where the session came from: a workspace prunes what it built and
 * leaves alone what it merely found. `always` authorizes pruning for one
 * operation; it does not stamp or otherwise adopt the session.
 */
export function mayPrune(policy: PrunePolicy, owned: boolean): boolean {
  if (policy === "never") return false;
  if (policy === "always") return true;
  return owned;
}

packages/workspace/src/planning.ts.content:
import type { AbortLike } from "libtmux";
import type { PaneId, SessionId, WindowId } from "libtmux/common";
import type { Server } from "libtmux/server";
import type { Session } from "libtmux/session";
import type { Window } from "libtmux/window";
import type { Workspace } from "./config.js";
import { mayPrune, ownedByWorkspace, type PrunePolicy } from "./ownership.js";

/** One existing window placement named by a workspace plan. */
export interface WorkspaceWindowPlacement {
  readonly id: WindowId;
  readonly index: number;
  readonly name: string | null;
  readonly position: number;
  readonly sessionId: SessionId;
}

/** A window that applying would create. */
export interface WorkspaceWindowCreation {
  readonly name?: string;
  readonly position: number;
}

/** Panes that applying would create in one window position. */
export interface WorkspacePaneCreation {
  readonly count: number;
  readonly windowPosition: number;
}

/** Existing panes that applying would destroy. */
export interface WorkspacePaneRemoval {
  readonly paneIds: readonly PaneId[];
  readonly window: WorkspaceWindowPlacement;
}

/** How applying would remove an existing window placement. */
export interface WorkspaceWindowRemoval {
  readonly action: "kill" | "unlink";
  readonly window: WorkspaceWindowPlacement;
}

/** One existing window rename, identified independently of its current name. */
export interface WorkspaceWindowRename {
  readonly from: string | null;
  readonly to: string;
  readonly window: WorkspaceWindowPlacement;
}

/** Surplus topology retained because removing it would exceed the policy. */
export type WorkspaceRetention =
  | {
      readonly count: number;
      readonly kind: "panes";
      readonly reason: "pruning-disabled" | "shared-window";
      readonly window: WorkspaceWindowPlacement;
    }
  | {
      readonly kind: "window";
      readonly reason: "grouped-session" | "pruning-disabled";
      readonly window: WorkspaceWindowPlacement;
    };

/** Session, window, and pane membership changes an apply would make. */
export interface WorkspacePlan {
  /** Windows the apply would create, by the position they would take. */
  readonly createsWindows: readonly WorkspaceWindowCreation[];
  /** Whether the session itself would be created. */
  readonly createsSession: boolean;
  /** Panes the apply would create, grouped by desired window position. */
  readonly createsPanes: readonly WorkspacePaneCreation[];
  /** Panes the apply would destroy, with their containing placement. */
  readonly removesPanes: readonly WorkspacePaneRemoval[];
  /** Window placements the apply would kill or unlink. */
  readonly removesWindows: readonly WorkspaceWindowRemoval[];
  /** Whether this workspace created the session it found. */
  readonly owned: boolean;
  /** Existing windows the apply would rename. */
  readonly renamesWindows: readonly WorkspaceWindowRename[];
  /**
   * Surplus this apply will leave alone, and why.
   *
   * Empty when nothing is surplus or the policy removes it. A non-empty list on
   * a session the workspace did not create is the case `prune: "owned"` exists
   * for: the file and the server disagree, and the file does not get to win by
   * default.
   */
  readonly retains: readonly WorkspaceRetention[];
}

/**
 * The session this workspace names, on a server that may not be running yet.
 *
 * Acquisition raises on an unreachable server rather than reading as empty,
 * which is the answer a caller asking what is there needs. Building from
 * nothing is the ordinary starting point here, though, and a socket with no
 * daemon behind it is holding this session in the way an empty server is: not
 * at all.
 */
export async function runningSession(
  server: Server,
  name: string,
  acquisition: { signal?: AbortLike } = {},
): Promise<Session | undefined> {
  // Server.isAlive() takes no options: it is a fixed, cheap probe with no
  // signal to thread through until libtmux's own signature grows one.
  if (!(await server.isAlive())) return undefined;
  return (await server.snapshot(acquisition)).sessions.oneOrUndefined({ name });
}

export async function planWorkspace(
  server: Server,
  workspace: Workspace,
  prune: PrunePolicy,
  acquisition: { signal?: AbortLike } = {},
): Promise<WorkspacePlan> {
  const existing = await runningSession(server, workspace.session_name, acquisition);
  if (existing === undefined) {
    return Object.freeze({
      createsPanes: freezeEntries(
        workspace.windows.map((window, windowPosition) => ({
          count: window.panes.length,
          windowPosition,
        })),
      ),
      createsSession: true,
      createsWindows: freezeEntries(
        workspace.windows.map((window, position) => ({
          ...(window.window_name === undefined ? {} : { name: window.window_name }),
          position,
        })),
      ),
      owned: true,
      removesPanes: Object.freeze([]),
      removesWindows: Object.freeze([]),
      renamesWindows: Object.freeze([]),
      retains: Object.freeze([]),
    });
  }

  const owned = await ownedByWorkspace(existing, workspace.session_name, acquisition);
  const pruning = mayPrune(prune, owned);
  const current = existing.windows.toArray();
  const createsWindows: WorkspaceWindowCreation[] = [];
  const createsPanes: WorkspacePaneCreation[] = [];
  const removesPanes: WorkspacePaneRemoval[] = [];
  const removesWindows: WorkspaceWindowRemoval[] = [];
  const renamesWindows: WorkspaceWindowRename[] = [];
  const retains: WorkspaceRetention[] = [];

  for (const [index, desired] of workspace.windows.entries()) {
    const window = current[index];
    const wanted = desired.panes.length;
    if (window === undefined) {
      createsWindows.push({
        ...(desired.window_name === undefined ? {} : { name: desired.window_name }),
        position: index,
      });
      createsPanes.push({ count: wanted, windowPosition: index });
      continue;
    }
    const placement = workspaceWindowPlacement(window, index);
    if (desired.window_name !== undefined && window.name !== desired.window_name) {
      renamesWindows.push({ from: window.name, to: desired.window_name, window: placement });
    }
    const present = window.panes.length;
    if (present < wanted) {
      createsPanes.push({ count: wanted - present, windowPosition: index });
    }
    if (present <= wanted) continue;
    const count = present - wanted;
    if (!pruning) {
      retains.push({ count, kind: "panes", reason: "pruning-disabled", window: placement });
    } else if (windowIsShared(window)) {
      retains.push({ count, kind: "panes", reason: "shared-window", window: placement });
    } else {
      removesPanes.push({
        paneIds: Object.freeze(
          window.panes
            .toArray()
            .slice(wanted)
            .map(({ id }) => id),
        ),
        window: placement,
      });
    }
  }

  const surplusWindows = current.slice(workspace.windows.length);
  for (const [offset, window] of surplusWindows.entries()) {
    const placement = workspaceWindowPlacement(window, workspace.windows.length + offset);
    if (!pruning) {
      retains.push({ kind: "window", reason: "pruning-disabled", window: placement });
    } else if (existing.grouped !== false) {
      retains.push({ kind: "window", reason: "grouped-session", window: placement });
    } else {
      removesWindows.push({
        action: windowIsShared(window) ? "unlink" : "kill",
        window: placement,
      });
    }
  }

  return Object.freeze({
    createsPanes: freezeEntries(createsPanes),
    createsSession: false,
    createsWindows: freezeEntries(createsWindows),
    owned,
    removesPanes: freezeEntries(removesPanes),
    removesWindows: freezeEntries(removesWindows),
    renamesWindows: freezeEntries(renamesWindows),
    retains: freezeEntries(retains),
  });
}

function freezeEntries<Entry extends object>(
  entries: readonly Entry[],
): readonly Readonly<Entry>[] {
  return Object.freeze(entries.map((entry) => Object.freeze(entry)));
}

function workspaceWindowPlacement(window: Window, position: number): WorkspaceWindowPlacement {
  return Object.freeze({
    id: window.id,
    index: window.index,
    name: window.name,
    position,
    sessionId: window.format.session_id,
  });
}

export function windowIsShared(window: Window): boolean {
  const session = window.session;
  return (
    session === undefined ||
    session.windows.count({ id: window.id }) !== 1 ||
    window.linkedSessions.count() !== 1
  );
}
